	private static final int MIN_UNLOCK_KILLS = 5;
	private static final Boss[] LADDER = values();

	// Matches the "id" of the boss's entry in drops.json, and is the key progress is saved under.
	private final String id;
	private final String displayName;
	// -1 for a boss that isn't an NPC, like the Wintertodt storm, which is scenery.
	private final int npcId;
	// The model for a boss that isn't an NPC, or -1. There are no gameval constants for models.
	private final int modelId;
	// The real boss's hitpoints.
	private final int hitpoints;
	// Takes double damage from this skill.
	private final Skill weakness;
	// Collection log slots, across every boss, needed to fight this one. It also needs unlockKills() of the one before.
	private final int unlockSlots;
	private final int idleAnimation;
	private final int walkAnimation;
	private final int defendAnimation;
	private final int deathAnimation;
	private final int spawnAnimation;

	// Big bosses take bigger hits so they still die in minutes: the square root of how much tougher than Obor they
	// are. The Nightmare's 7,800 hitpoints take about 4 minutes of training instead of 32.
	double damageScale()
	{
		return Math.max(1, Math.sqrt(hitpoints / (double) REFERENCE_HITPOINTS));
	}

	// How long a kill takes at a typical pace, without the weakness bonus.
	double typicalKillSeconds()
	{
		return hitpoints / (SkillRates.DAMAGE_PER_HOUR / 3600 * damageScale());
	}

	// The boss before this one on the ladder, or null for the first.
	Boss previous()
	{
		return ordinal() == 0 ? null : LADDER[ordinal() - 1];
	}

	// Kills of the boss before this one needed to fight it, so you meet each boss on the way up: about 10 minutes of
	// fighting it, rounded up to a multiple of 5. None for the bosses you start with.
	int unlockKills()
	{
		Boss previous = previous();
		if (previous == null || unlockSlots == 0)
		{
			return 0;
		}
		int kills = (int) Math.ceil(UNLOCK_FIGHT_SECONDS / previous.typicalKillSeconds() / 5) * 5;
		return Math.max(MIN_UNLOCK_KILLS, kills);
	}

	static Boss byId(String id)
	{
		for (Boss boss : values())
		{
			if (boss.id.equals(id))
			{
				return boss;
			}
		}
		return null;
	}
}

package com.idlebosses;

import lombok.Getter;
import net.runelite.api.Skill;

// The boss you're fighting: its health, whether it's a superior, your kill streak, and damage still to land.
// There's no limit on a hit, and damage past a boss's last hitpoint carries on to the next boss.
// Pure state, so it can be tested without a client.
@Getter
final class BossFight
{
	static final double WEAKNESS_MULTIPLIER = 2;
	// Each kill in a row adds 1% damage, up to 25%.
	static final int MAX_STREAK_BONUS = 25;
	static final long STREAK_TIMEOUT_MILLIS = 60_000;
	static final int SUPERIOR_HP_MULTIPLIER = 2;

	private Boss boss;
	private int hp;
	private int maxHp;
	private boolean superior;
	private int streak;
	private long lastXpMillis;
	// Damage from XP drops that hasn't landed yet: what's left after a kill, waiting for the next boss.
	private long pending;
	// XP drops that have hit this boss, for the Soulreaper axe.
	private int hitsOnBoss;
	// Poisoned by the abyssal tentacle until it dies.
	private boolean poisoned;
	// Health the Voidwaker took in its last finishing blow, to show as a hitsplat.
	private long executed;

	// Brings in a boss at full health. Pending damage is kept, so it lands on this one.
	void start(Boss boss, boolean superior)
	{
		this.boss = boss;
		this.superior = superior;
		maxHp = boss.getHitpoints() * (superior ? SUPERIOR_HP_MULTIPLIER : 1);
		hp = maxHp;
		hitsOnBoss = 0;
		poisoned = false;
	}

	static long damage(Skill skill, int xp, Skill weakness, int streak)
	{
		return damage(skill, xp, weakness, streak, 1);
	}

	// Scale makes hits bigger against tougher bosses; see Boss.damageScale.
	static long damage(Skill skill, int xp, Skill weakness, int streak, double scale)
	{
		int xpPerHour = SkillRates.xpPerHour(skill);
		if (xpPerHour <= 0 || xp <= 0)
		{
			return 0;
		}
		double damage = xp * SkillRates.DAMAGE_PER_HOUR / xpPerHour;
		if (skill == weakness)
		{
			damage *= WEAKNESS_MULTIPLIER;
		}
		damage *= 1 + Math.min(streak, MAX_STREAK_BONUS) / 100.0;
		return Math.max(1, Math.round(damage * scale));
	}

	int streakBonus()
	{
		return Math.min(streak, MAX_STREAK_BONUS);
	}

	// Adds an XP drop's damage, to be landed with land(). Returns the damage, or 0 if the skill doesn't hit.
	long hit(Skill skill, int xp, long nowMillis)
	{
		long damage = baseDamage(skill, xp);
		if (damage > 0)
		{
			xpGained(nowMillis);
			pending += damage;
		}
		return damage;
	}

	// What an XP drop hits this boss for before gear, or 0 if the skill doesn't hit.
	long baseDamage(Skill skill, int xp)
	{
		return boss == null ? 0 : damage(skill, xp, boss.getWeakness(), streak, boss.damageScale());
	}

	// An XP drop keeps the streak, and the cannon and poison, going.
	void xpGained(long nowMillis)
	{
		lastXpMillis = nowMillis;
	}

	// True while you're training: there's been XP within the streak's time.
	boolean isActive(long nowMillis)
	{
		return lastXpMillis > 0 && nowMillis - lastXpMillis <= STREAK_TIMEOUT_MILLIS;
	}

	// Adds damage to land with land(), without counting as XP.
	void addDamage(long damage)
	{
		if (boss != null && damage > 0)
		{
			pending += damage;
		}
	}

	void addHitOnBoss()
	{
		hitsOnBoss++;
	}

	void poison()
	{
		poisoned = true;
	}

	// The health the Voidwaker last finished off, then 0 until it does again.
	long takeExecuted()
	{
		long taken = executed;
		executed = 0;
		return taken;
	}

	boolean land()
	{
		return land(0);
	}

	// Lands pending damage on the boss. True when that kills it: start the next boss and call again for the rest.
	// A boss left under executeBelow of its health is finished off.
	boolean land(double executeBelow)
	{
		if (boss == null || pending <= 0)
		{
			return false;
		}
		long used = Math.min(pending, hp);
		hp -= used;
		pending -= used;
		if (hp > 0 && hp < maxHp * executeBelow)
		{
			executed += hp;
			hp = 0;
		}
		if (hp > 0)
		{
			return false;
		}
		streak++;
		return true;
	}

	void clearPending()
	{
		pending = 0;
	}

	// The streak just lost, or 0.
	int expireStreak(long nowMillis)
	{
		if (streak > 0 && nowMillis - lastXpMillis > STREAK_TIMEOUT_MILLIS)
		{
			int lost = streak;
			streak = 0;
			return lost;
		}
		return 0;
	}
}

package com.idlebosses;

import lombok.RequiredArgsConstructor;

// One animation frame of a boss, flattened to 2D triangles in drawing order (furthest first), in model units.
// Never changed once made, so it can be handed to the Swing thread.
@RequiredArgsConstructor
final class BossFrame
{
	// Three corners a triangle.
	final float[] x;
	final float[] y;
	final int[] rgb;
	final int triangles;
	final float minX;
	final float maxX;
	final float minY;
	final float maxY;
}

package com.idlebosses;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.Setter;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

// The box on screen: the boss with your streak and its weakness on it, its health, its collection log with the last
// kill's new items framed, and your cannon and coins. A weapon effect that triggers shows as a banner across the boss.
// Its height only changes with the boss, never between kills.
class BossHudOverlay extends OverlayPanel
{
	private static final int WIDTH = 170;
	private static final Color NAME_COLOR = new Color(255, 152, 31);
	private static final Color SUPERIOR_COLOR = new Color(224, 112, 255);
	private static final Color GOLD_COLOR = new Color(255, 215, 0);
	private static final Color WEAK_COLOR = new Color(95, 224, 95);
	private static final Color DIM_COLOR = new Color(176, 168, 144);
	private static final Color STREAK_COLOR = new Color(255, 210, 122);
	private static final Color EMPTY_COLOR = new Color(255, 80, 80);
	private static final Color CHIP_COLOR = new Color(0, 0, 0, 120);
	private static final Color BANNER_COLOR = new Color(0, 0, 0, 150);
	private static final Color SPECIAL_COLOR = new Color(255, 230, 90);
	private static final float FADED_ALPHA = 0.4f;
	private static final long BANNER_MILLIS = 1_200;
	private static final long BANNER_FADE_IN_MILLIS = 100;
	private static final long BANNER_FADE_OUT_MILLIS = 300;

	private final IdleBossesPlugin plugin;
	private final IdleBossesConfig config;
	private final SkillIconManager skillIconManager;
	private final ItemManager itemManager;
	// Weapon icons at half size for the banner, filled in as they load.
	private final Map<Gear, BufferedImage> weaponIcons = new ConcurrentHashMap<>();
	private final Set<Gear> requestedIcons = EnumSet.noneOf(Gear.class);
	private final BossWindow window;
	private final StatusRow statusRow = new StatusRow();
	private final HealthBar healthBar = new HealthBar();
	private final LogGrid logGrid;
	private final Footer footer;

	@Inject
	BossHudOverlay(IdleBossesPlugin plugin, IdleBossesConfig config, BossPortrait portrait, SplatSprites splatSprites,
		ItemManager itemManager, SkillIconManager skillIconManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;
		this.itemManager = itemManager;
		window = new BossWindow(portrait, splatSprites);
		logGrid = new LogGrid(itemManager);
		footer = new Footer(itemManager);
		setPosition(OverlayPosition.TOP_LEFT);
		// RuneLite draws an overlay you've dragged somewhere above every interface, so it would cover the bank. Drawn
		// with the scene, the game's interfaces always go over it.
		setLayer(OverlayLayer.ABOVE_SCENE);
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.setGap(new Point(0, 3));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BossFight fight = plugin.getFight();
		Boss boss = fight.getBoss();
		if (!config.showHud() || !plugin.isReady() || boss == null)
		{
			return null;
		}
		Progress progress = plugin.getProgress();

		boolean gold = plugin.isLogComplete(boss);
		String name = (fight.isSuperior() ? "Superior " : "") + boss.getDisplayName();
		panelComponent.getChildren().add(LineComponent.builder()
			.left(name)
			.leftColor(fight.isSuperior() ? SUPERIOR_COLOR : gold ? GOLD_COLOR : NAME_COLOR)
			.right("KC " + QuantityFormatter.formatNumber(progress.kills(boss)))
			.build());

		Status status = new Status(skillIconManager.getSkillImage(boss.getWeakness(), true),
			boss.getWeakness() == plugin.getLastSkill(), fight.getStreak(), fight.streakBonus());
		Banner banner = banner(plugin.getSpecial());
		if (config.showBossInHud())
		{
			window.status = status;
			window.banner = banner;
			panelComponent.getChildren().add(window);
		}
		else
		{
			statusRow.status = status;
			statusRow.banner = banner;
			panelComponent.getChildren().add(statusRow);
		}

		healthBar.update(fight.getHp(), fight.getMaxHp());
		panelComponent.getChildren().add(healthBar);

		List<Integer> log = plugin.logItems(boss);
		int owned = progress.logCount(log);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Collection log")
			.leftColor(DIM_COLOR)
			.right(owned + " / " + log.size())
			.rightColor(gold ? GOLD_COLOR : Color.WHITE)
			.build());
		logGrid.set(boss, log, progress, plugin.getLastLogItems(), plugin.getLastRareLogItems());
		panelComponent.getChildren().add(logGrid);

		footer.set(progress.cannon, progress.coins());
		panelComponent.getChildren().add(footer);
		return super.render(graphics);
	}

	// The banner for a weapon effect that triggered in the last moment, or null.
	private Banner banner(IdleBossesPlugin.Special special)
	{
		if (special == null || special.getWeapon() == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - special.getMillis();
		if (age < 0 || age >= BANNER_MILLIS)
		{
			return null;
		}
		float alpha = age < BANNER_FADE_IN_MILLIS ? (float) age / BANNER_FADE_IN_MILLIS
			: Math.min(1, (float) (BANNER_MILLIS - age) / BANNER_FADE_OUT_MILLIS);
		Gear weapon = special.getWeapon();
		if (requestedIcons.add(weapon))
		{
			AsyncBufferedImage icon = itemManager.getImage(weapon.getItemId());
			icon.onLoaded(() -> weaponIcons.put(weapon, half(icon)));
		}
		String name = weapon.getDisplayName().replace(" (i)", "");
		return new Banner(weaponIcons.get(weapon), name + "  " + special.getLabel(), alpha);
	}

	// A weapon effect that just triggered: the weapon's icon and what it did, fading in and out.
	private static final class Banner
	{
		final BufferedImage icon;
		final String text;
		final float alpha;

		Banner(BufferedImage icon, String text, float alpha)
		{
			this.icon = icon;
			this.text = text;
			this.alpha = alpha;
		}
	}

	private static void drawBanner(Graphics2D graphics, Banner banner, int x, int y)
	{
		if (banner == null)
		{
			return;
		}
		Composite composite = graphics.getComposite();
		Font font = graphics.getFont();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, banner.alpha)));
		graphics.setFont(FontManager.getRunescapeSmallFont());
		int iconWidth = banner.icon == null ? 0 : banner.icon.getWidth() + 3;
		graphics.setColor(BANNER_COLOR);
		graphics.fillRect(x, y, 2 + iconWidth + graphics.getFontMetrics().stringWidth(banner.text) + 5, 18);
		if (banner.icon != null)
		{
			graphics.drawImage(banner.icon, x + 2, y + 1, null);
		}
		text(graphics, banner.text, x + 2 + iconWidth, y + 13, SPECIAL_COLOR);
		graphics.setFont(font);
		graphics.setComposite(composite);
	}

	// What goes on the boss: the streak, and the weakness skill and whether you're training it.
	private static final class Status
	{
		final BufferedImage skillIcon;
		final boolean weak;
		final int streak;
		final int bonus;

		Status(BufferedImage skillIcon, boolean weak, int streak, int bonus)
		{
			this.skillIcon = skillIcon;
			this.weak = weak;
			this.streak = streak;
			this.bonus = bonus;
		}
	}

	// The weakness skill's icon, its right edge at right: lit with "2x" beside it while you train it, faded otherwise.
	private static void drawWeakness(Graphics2D graphics, Status status, int right, int y)
	{
		if (status.skillIcon == null)
		{
			return;
		}
		int x = right - status.skillIcon.getWidth();
		Composite composite = graphics.getComposite();
		if (!status.weak)
		{
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, FADED_ALPHA));
		}
		graphics.drawImage(status.skillIcon, x, y, null);
		graphics.setComposite(composite);
		if (status.weak)
		{
			Font font = graphics.getFont();
			graphics.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics metrics = graphics.getFontMetrics();
			text(graphics, "2x", x - 2 - metrics.stringWidth("2x"), y + (status.skillIcon.getHeight() + metrics.getAscent()) / 2 - 1,
				WEAK_COLOR);
			graphics.setFont(font);
		}
	}

	// The streak on a dark chip, if there is one.
	private static void drawStreak(Graphics2D graphics, Status status, int x, int y)
	{
		if (status.streak <= 0)
		{
			return;
		}
		Font font = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		String streak = "x" + status.streak + "  +" + status.bonus + "%";
		graphics.setColor(CHIP_COLOR);
		graphics.fillRect(x, y, graphics.getFontMetrics().stringWidth(streak) + 6, 14);
		text(graphics, streak, x + 3, y + 11, STREAK_COLOR);
		graphics.setFont(font);
	}

	private static void text(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	// The animated boss, in a darker box, with the streak at the bottom left and the weakness at the top right.
	private static final class BossWindow implements LayoutableRenderableEntity
	{
		private static final int HEIGHT = 100;
		private static final Color BACKGROUND = new Color(20, 17, 13, 120);

		private final BossPortrait portrait;
		private final SplatSprites splatSprites;
		private final BossView view = new BossView();
		private Status status;
		private Banner banner;

		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(WIDTH, HEIGHT);
		private final Rectangle bounds = new Rectangle();

		BossWindow(BossPortrait portrait, SplatSprites splatSprites)
		{
			this.portrait = portrait;
			this.splatSprites = splatSprites;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			int x = preferredLocation.x;
			int y = preferredLocation.y;
			int width = preferredSize.width;
			graphics.setColor(BACKGROUND);
			graphics.fillRect(x, y, width, HEIGHT);
			view.paint(graphics, x, y, width, HEIGHT, portrait.getSnapshot(), splatSprites);
			// A banner has the top of the box to itself while it shows.
			if (banner == null)
			{
				drawWeakness(graphics, status, x + width - 3, y + 3);
			}
			drawStreak(graphics, status, x + 3, y + HEIGHT - 17);
			drawBanner(graphics, banner, x + 3, y + 3);
			bounds.setBounds(x, y, width, HEIGHT);
			return new Dimension(width, HEIGHT);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	// The streak and weakness on their own row, when the boss isn't shown.
	private static final class StatusRow implements LayoutableRenderableEntity
	{
		private static final int HEIGHT = 18;

		private Status status;
		private Banner banner;

		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(WIDTH, HEIGHT);
		private final Rectangle bounds = new Rectangle();

		@Override
		public Dimension render(Graphics2D graphics)
		{
			int x = preferredLocation.x;
			int y = preferredLocation.y;
			if (banner == null)
			{
				drawStreak(graphics, status, x, y + 2);
				drawWeakness(graphics, status, x + preferredSize.width, y);
			}
			drawBanner(graphics, banner, x, y);
			bounds.setBounds(x, y, preferredSize.width, HEIGHT);
			return new Dimension(preferredSize.width, HEIGHT);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	// A health bar whose lost chunk drains away after a moment, so each hit is easy to see.
	private static final class HealthBar implements LayoutableRenderableEntity
	{
		private static final int HEIGHT = 14;
		private static final long DRAIN_DELAY_MILLIS = 250;
		// Fraction of the bar drained each millisecond.
		private static final double DRAIN_SPEED = 0.0015;
		private static final Color BACKGROUND = new Color(94, 16, 16);
		private static final Color HEALTH = new Color(31, 154, 31);
		private static final Color DRAIN = new Color(240, 208, 112);

		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(WIDTH, HEIGHT);
		private final Rectangle bounds = new Rectangle();

		private double shown = 1;
		private double trail = 1;
		private long changedMillis;
		private long lastFrameMillis;
		private String text = "";

		void update(int hp, int maxHp)
		{
			double fraction = maxHp > 0 ? (double) hp / maxHp : 0;
			if (fraction > shown)
			{
				// A new boss: no trail.
				trail = fraction;
			}
			else if (fraction < shown)
			{
				changedMillis = System.currentTimeMillis();
			}
			shown = fraction;
			text = hp + " / " + maxHp;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			long now = System.currentTimeMillis();
			if (trail > shown && now - changedMillis > DRAIN_DELAY_MILLIS)
			{
				trail = Math.max(shown, trail - (now - lastFrameMillis) * DRAIN_SPEED);
			}
			lastFrameMillis = now;

			int x = preferredLocation.x;
			int y = preferredLocation.y;
			int width = preferredSize.width;
			graphics.setColor(BACKGROUND);
			graphics.fillRect(x, y, width, HEIGHT);
			graphics.setColor(DRAIN);
			graphics.fillRect(x, y, (int) Math.round(width * trail), HEIGHT);
			graphics.setColor(HEALTH);
			graphics.fillRect(x, y, (int) Math.round(width * shown), HEIGHT);

			FontMetrics metrics = graphics.getFontMetrics();
			int textX = x + (width - metrics.stringWidth(text)) / 2;
			int textY = y + (HEIGHT + metrics.getAscent()) / 2 - 1;
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, textX + 1, textY + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(text, textX, textY);

			bounds.setBounds(x, y, width, HEIGHT);
			return new Dimension(width, HEIGHT);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	// Half the size, each pixel the average of the four it covers. Shrinking by exactly half keeps item icons sharp,
	// where scaling them by any other amount smears them.
	static BufferedImage half(BufferedImage image)
	{
		int width = image.getWidth() / 2;
		int height = image.getHeight() / 2;
		BufferedImage half = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int alpha = 0;
				int red = 0;
				int green = 0;
				int blue = 0;
				for (int i = 0; i < 4; i++)
				{
					int pixel = image.getRGB(x * 2 + i % 2, y * 2 + i / 2);
					int a = pixel >>> 24;
					alpha += a;
					red += (pixel >> 16 & 0xFF) * a;
					green += (pixel >> 8 & 0xFF) * a;
					blue += (pixel & 0xFF) * a;
				}
				half.setRGB(x, y, alpha == 0 ? 0 : (alpha / 4) << 24 | red / alpha << 16 | green / alpha << 8 | blue / alpha);
			}
		}
		return half;
	}

	// Every item on the boss's log: full size for a log of up to 8, so it's as sharp as your inventory, and exactly half
	// size for a bigger one. Ones you have sit on a warm tile, missing ones are faded, and the last kill's new ones are
	// framed.
	private static final class LogGrid implements LayoutableRenderableEntity
	{
		private static final int FULL_SIZE_ITEMS = 8;
		private static final int ICON_WIDTH = 36;
		private static final int ICON_HEIGHT = 32;
		private static final int GAP = 2;
		private static final float MISSING_ALPHA = 0.3f;
		private static final Color OWNED_TILE = new Color(255, 190, 90, 70);
		private static final Color MISSING_TILE = new Color(0, 0, 0, 70);
		private static final Color LOG_FRAME = new Color(255, 152, 31);
		private static final Color RARE_FRAME = new Color(224, 112, 255);

		// An item's icon at the size the grid draws it, and a faded copy for when you don't have it.
		private static final class Sprite
		{
			final BufferedImage owned;
			final BufferedImage missing;

			Sprite(BufferedImage owned)
			{
				this.owned = owned;
				missing = ImageUtil.alphaOffset(ImageUtil.grayscaleImage(owned), MISSING_ALPHA);
			}
		}

		private final ItemManager itemManager;
		private Boss boss;
		private List<Integer> log = List.of();
		// Filled in as each icon loads.
		private Sprite[] sprites = new Sprite[0];
		private Progress progress;
		private Set<Integer> newItems = Set.of();
		private Set<Integer> rareItems = Set.of();

		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(WIDTH, 0);
		private final Rectangle bounds = new Rectangle();

		LogGrid(ItemManager itemManager)
		{
			this.itemManager = itemManager;
		}

		void set(Boss boss, List<Integer> log, Progress progress, Set<Integer> newItems, Set<Integer> rareItems)
		{
			if (boss != this.boss)
			{
				this.boss = boss;
				this.log = log;
				boolean full = log.size() <= FULL_SIZE_ITEMS;
				Sprite[] loading = new Sprite[log.size()];
				for (int i = 0; i < log.size(); i++)
				{
					int slot = i;
					AsyncBufferedImage icon = itemManager.getImage(log.get(i));
					icon.onLoaded(() -> loading[slot] = new Sprite(full ? icon : half(icon)));
				}
				sprites = loading;
			}
			this.progress = progress;
			this.newItems = newItems;
			this.rareItems = rareItems;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			boolean full = log.size() <= FULL_SIZE_ITEMS;
			int cellWidth = full ? ICON_WIDTH : ICON_WIDTH / 2;
			int cellHeight = full ? ICON_HEIGHT : ICON_HEIGHT / 2;
			int perRow = Math.max(1, (preferredSize.width + GAP) / (cellWidth + GAP));
			int rows = (log.size() + perRow - 1) / perRow;
			for (int i = 0; i < log.size(); i++)
			{
				int itemId = log.get(i);
				boolean owned = progress.hasLogItem(itemId);
				int x = preferredLocation.x + (i % perRow) * (cellWidth + GAP);
				int y = preferredLocation.y + (i / perRow) * (cellHeight + GAP);
				graphics.setColor(owned ? OWNED_TILE : MISSING_TILE);
				graphics.fillRect(x, y, cellWidth, cellHeight);
				Sprite sprite = sprites[i];
				if (sprite != null)
				{
					graphics.drawImage(owned ? sprite.owned : sprite.missing, x, y, null);
				}
				if (newItems.contains(itemId))
				{
					graphics.setColor(rareItems.contains(itemId) ? RARE_FRAME : LOG_FRAME);
					graphics.drawRect(x, y, cellWidth - 1, cellHeight - 1);
				}
			}

			int height = rows * cellHeight + Math.max(0, rows - 1) * GAP;
			bounds.setBounds(preferredLocation.x, preferredLocation.y, preferredSize.width, height);
			return new Dimension(preferredSize.width, height);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}

	// Your cannon's load on the left, once you have one, and your coins on the right, with half-size icons.
	private static final class Footer implements LayoutableRenderableEntity
	{
		private static final int HEIGHT = 18;
		private static final int ICON_WIDTH = 18;

		private final ItemManager itemManager;
		private boolean requested;
		private BufferedImage ballIcon;
		private BufferedImage graniteIcon;
		private BufferedImage coinsIcon;
		private Progress.CannonState cannon;
		private long coins;

		@Setter
		private Point preferredLocation = new Point();
		@Setter
		private Dimension preferredSize = new Dimension(WIDTH, HEIGHT);
		private final Rectangle bounds = new Rectangle();

		Footer(ItemManager itemManager)
		{
			this.itemManager = itemManager;
		}

		void set(Progress.CannonState cannon, long coins)
		{
			this.cannon = cannon;
			this.coins = coins;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			if (!requested)
			{
				requested = true;
				AsyncBufferedImage ball = itemManager.getImage(ItemID.MCANNONBALL);
				ball.onLoaded(() -> ballIcon = half(ball));
				AsyncBufferedImage granite = itemManager.getImage(ItemID.GRANITE_CANNONBALL);
				granite.onLoaded(() -> graniteIcon = half(granite));
				AsyncBufferedImage pile = itemManager.getImage(ItemID.COINS_10000);
				pile.onLoaded(() -> coinsIcon = half(pile));
			}
			int x = preferredLocation.x;
			int y = preferredLocation.y;
			int width = preferredSize.width;
			FontMetrics metrics = graphics.getFontMetrics();
			int textY = y + HEIGHT - 4;
			if (cannon.owned)
			{
				BufferedImage icon = cannon.loadedGranite > 0 ? graniteIcon : ballIcon;
				if (icon != null)
				{
					graphics.drawImage(icon, x - 1, y + 1, null);
				}
				text(graphics, cannon.loaded > 0 ? cannon.loaded + " / " + Shop.CANNON_CAPACITY : "Empty", x + ICON_WIDTH + 1, textY,
					cannon.loaded > 0 ? Color.WHITE : EMPTY_COLOR);
			}
			String amount = QuantityFormatter.quantityToStackSize(coins);
			int amountX = x + width - metrics.stringWidth(amount);
			if (coinsIcon != null)
			{
				graphics.drawImage(coinsIcon, amountX - ICON_WIDTH - 1, y + 1, null);
			}
			text(graphics, amount, amountX, textY, Color.YELLOW);
			bounds.setBounds(x, y, width, HEIGHT);
			return new Dimension(width, HEIGHT);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}
	}
}

package com.idlebosses;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;

// Loads boss models and works out animation timings, for both the walking boss and the portrait.
// Only used on the client thread.
final class BossModels
{
	// A death animation's last frame is often held for many seconds, so it's cut this many client cycles (20ms) in.
	private static final int DEATH_HOLD_CYCLES = 30;
	private static final int MAX_DEATH_CYCLES = 200;
	private static final int MODEL_SCALE_UNIT = 128;
	// Colour values are 6 bits of hue, 3 of saturation and 7 of lightness.
	private static final int SUPERIOR_HUE = 51;
	private static final int SUPERIOR_SATURATION = 5;
	private static final int GOLD_HUE = 8;
	private static final int GOLD_SATURATION = 6;
	private static final int GOLD_LIGHTEN = 12;

	private BossModels()
	{
	}

	// The boss's model, copied so the game's own cached models aren't changed. With tiles above 0 it's scaled to
	// that many tiles wide; otherwise it keeps its own size.
	static ModelData load(Client client, Boss boss, MiniBoss.Variant variant, double tiles)
	{
		ModelData data = boss.getModelId() >= 0 ? loadScenery(client, boss.getModelId()) : loadNpc(client, boss.getNpcId());
		if (data == null)
		{
			return null;
		}

		// Sized by how wide the model really is: some NPCs claim one tile while their model spans five.
		if (tiles > 0)
		{
			int scale = (int) Math.round(MODEL_SCALE_UNIT * tiles * Perspective.LOCAL_TILE_SIZE / Math.max(1, width(data)));
			data.scale(scale, scale, scale);
		}

		if (variant != MiniBoss.Variant.NORMAL)
		{
			data = data.cloneColors();
			short[] colors = data.getFaceColors();
			for (int i = 0; i < colors.length; i++)
			{
				colors[i] = tint(colors[i], variant);
			}
		}
		return data;
	}

	// The NPC's models at its own size and colours, copied so the game's cached models aren't changed.
	private static ModelData loadNpc(Client client, int npcId)
	{
		NPCComposition npc = client.getNpcDefinition(npcId);
		if (npc == null || npc.getModels() == null || npc.getModels().length == 0)
		{
			return null;
		}

		int[] ids = npc.getModels();
		ModelData[] parts = new ModelData[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			parts[i] = client.loadModelData(ids[i]);
			if (parts[i] == null)
			{
				return null;
			}
		}

		ModelData data = (parts.length == 1 ? parts[0] : client.mergeModels(parts)).shallowCopy().cloneVertices();
		data.scale(npc.getWidthScale(), npc.getHeightScale(), npc.getWidthScale());

		// Some bosses are another model in different colours, like the three Dagannoth Kings.
		short[] find = npc.getColorToReplace();
		short[] replace = npc.getColorToReplaceWith();
		if (find != null && replace != null)
		{
			data = data.cloneColors();
			for (int i = 0; i < Math.min(find.length, replace.length); i++)
			{
				data.recolor(find[i], replace[i]);
			}
		}
		return data;
	}

	private static ModelData loadScenery(Client client, int modelId)
	{
		ModelData data = client.loadModelData(modelId);
		return data == null ? null : data.shallowCopy().cloneVertices();
	}

	// The model's widest span across the ground, in local units.
	private static float width(ModelData data)
	{
		float[] xs = data.getVerticesX();
		float[] zs = data.getVerticesZ();
		float minX = Float.MAX_VALUE;
		float maxX = -Float.MAX_VALUE;
		float minZ = Float.MAX_VALUE;
		float maxZ = -Float.MAX_VALUE;
		for (int i = 0; i < data.getVerticesCount(); i++)
		{
			minX = Math.min(minX, xs[i]);
			maxX = Math.max(maxX, xs[i]);
			minZ = Math.min(minZ, zs[i]);
			maxZ = Math.max(maxZ, zs[i]);
		}
		return Math.max(maxX - minX, maxZ - minZ);
	}

	static short tint(short color, MiniBoss.Variant variant)
	{
		int lightness = color & 0x7F;
		if (variant == MiniBoss.Variant.GOLD)
		{
			return (short) (GOLD_HUE << 10 | GOLD_SATURATION << 7 | Math.min(0x7F, lightness + GOLD_LIGHTEN));
		}
		return (short) (SUPERIOR_HUE << 10 | SUPERIOR_SATURATION << 7 | lightness);
	}

	// The game doesn't measure a model's height until it has drawn it, so measure it from the vertices.
	// Model Y points down from the feet, so the top is the most negative Y; the other side covers a flipped model.
	static int height(float[] verticesY)
	{
		float min = 0;
		float max = 0;
		for (float vertexY : verticesY)
		{
			min = Math.min(min, vertexY);
			max = Math.max(max, vertexY);
		}
		return Math.round(Math.max(-min, max));
	}

	// How long to show a death animation before taking the boss away, in client cycles.
	static int deathCycles(Animation animation)
	{
		if (animation == null)
		{
			return 0;
		}
		if (animation.isMayaAnim())
		{
			return Math.min(animation.getDuration(), MAX_DEATH_CYCLES);
		}
		int[] lengths = animation.getFrameLengths();
		if (lengths == null || lengths.length == 0)
		{
			return 0;
		}
		int total = 0;
		for (int i = 0; i < lengths.length - 1; i++)
		{
			total += lengths[i];
		}
		return Math.min(total + Math.min(lengths[lengths.length - 1], DEATH_HOLD_CYCLES), MAX_DEATH_CYCLES);
	}
}

package com.idlebosses;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

// The animated boss shown in the HUD and the sidebar: it idles, flinches with each hit, dies and respawns, using
// the boss's own animations. Runs on the client thread and publishes each frame as a Snapshot for the views.
@Singleton
class BossPortrait
{
	private static final int RESPAWN_DELAY_CYCLES = 30;
	private static final int MAX_SPLATS = BossView.SPLAT_OFFSETS.length;
	// Room around the idle pose for attacks and deaths that reach further.
	private static final float BOUNDS_MARGIN = 0.12f;

	private final Client client;

	private Boss boss;
	private MiniBoss.Variant variant = MiniBoss.Variant.NORMAL;
	private Model base;
	private AnimationController controller;
	private float[] bounds;
	private boolean dying;
	private boolean spawning;
	private int hideAtCycle = -1;
	private int spawnAtCycle = -1;
	private int lastCycle;
	private int lastFrame = -1;
	private boolean dirty;
	private BossFrame frame;
	private long fadeInMillis;
	private List<Splat> splats = List.of();

	@Getter
	private volatile Snapshot snapshot;

	@Inject
	BossPortrait(Client client)
	{
		this.client = client;
	}

	void set(Boss boss, MiniBoss.Variant variant)
	{
		if (boss == this.boss && variant == this.variant && snapshot != null && !dying)
		{
			return;
		}
		this.boss = boss;
		this.variant = variant;
		dying = false;
		hideAtCycle = -1;
		spawnAtCycle = -1;
		splats = List.of();
		spawn();
	}

	void clear()
	{
		boss = null;
		base = null;
		controller = null;
		frame = null;
		dying = false;
		spawning = false;
		hideAtCycle = -1;
		spawnAtCycle = -1;
		splats = List.of();
		snapshot = null;
	}

	// Splats are kept while one boss dies and the next appears, so a hit in between still shows on the new one.
	void hit(int damage, Hit.Type type)
	{
		if (boss == null)
		{
			return;
		}
		List<Splat> next = new ArrayList<>(splats);
		next.add(new Splat(damage, type, System.currentTimeMillis()));
		while (next.size() > MAX_SPLATS)
		{
			next.remove(0);
		}
		splats = List.copyOf(next);
		publish();

		if (base != null && !dying && !spawning && boss.getDefendAnimation() != -1)
		{
			playOnce(client.loadAnimation(boss.getDefendAnimation()), this::idle);
		}
	}

	// The boss died: play its death, then bring in the next one.
	void kill(Boss next, MiniBoss.Variant nextVariant)
	{
		Boss dead = boss;
		boss = next;
		variant = nextVariant;
		if (base == null || dying || dead == null)
		{
			if (!dying)
			{
				spawn();
			}
			return;
		}

		dying = true;
		spawning = false;
		Animation death = client.loadAnimation(dead.getDeathAnimation());
		hideAtCycle = client.getGameCycle() + BossModels.deathCycles(death);
		playOnce(death, this::finishDeath);
	}

	void clientTick()
	{
		int cycle = client.getGameCycle();
		int cycles = Math.max(1, Math.min(10, cycle - lastCycle));
		lastCycle = cycle;

		if (dying && cycle >= hideAtCycle)
		{
			finishDeath();
		}
		if (spawnAtCycle >= 0 && cycle >= spawnAtCycle)
		{
			spawnAtCycle = -1;
			spawn();
		}
		if (base == null)
		{
			return;
		}

		if (controller != null)
		{
			controller.tick(cycles);
		}
		// Finishing a death inside the tick takes the boss away.
		if (base == null)
		{
			return;
		}
		int at = controller == null ? -1 : controller.getFrame();
		if (dirty || at != lastFrame)
		{
			lastFrame = at;
			dirty = false;
			frame = ModelProjector.project(posed(), this::textureColor);
			publish();
		}
	}

	private void spawn()
	{
		base = null;
		controller = null;
		frame = null;
		snapshot = null;
		if (boss == null)
		{
			return;
		}
		ModelData data = BossModels.load(client, boss, variant, 0);
		if (data == null)
		{
			return;
		}
		base = data.light();

		// Fit the box to the first frame of the idle pose, so the zoom doesn't change as the boss moves.
		idle();
		BossFrame idle = ModelProjector.project(posed(), this::textureColor);
		float marginX = (idle.maxX - idle.minX) * BOUNDS_MARGIN;
		float marginY = (idle.maxY - idle.minY) * BOUNDS_MARGIN;
		bounds = new float[]{idle.minX - marginX, idle.maxX + marginX, idle.minY - marginY, idle.maxY};

		if (boss.getSpawnAnimation() != -1)
		{
			spawning = true;
			fadeInMillis = 0;
			playOnce(client.loadAnimation(boss.getSpawnAnimation()), this::idle);
		}
		else
		{
			fadeInMillis = System.currentTimeMillis();
		}
		dirty = true;
	}

	private void finishDeath()
	{
		if (!dying)
		{
			return;
		}
		dying = false;
		hideAtCycle = -1;
		base = null;
		controller = null;
		frame = null;
		snapshot = null;
		spawnAtCycle = client.getGameCycle() + RESPAWN_DELAY_CYCLES;
	}

	private void idle()
	{
		spawning = false;
		if (boss == null || dying)
		{
			return;
		}
		Animation idle = client.loadAnimation(boss.getIdleAnimation());
		controller = idle == null ? null : new AnimationController(client, idle);
		if (controller != null)
		{
			controller.loop();
		}
		dirty = true;
	}

	private void playOnce(Animation animation, Runnable after)
	{
		if (animation == null)
		{
			after.run();
			return;
		}
		controller = new AnimationController(client, animation);
		controller.setOnFinished(c -> after.run());
		dirty = true;
	}

	private int textureColor(int texture)
	{
		return client.getTextureProvider() == null ? 0 : client.getTextureProvider().getDefaultColor(texture);
	}

	private Model posed()
	{
		return controller == null || controller.getAnimation() == null ? base : controller.animate(base);
	}

	private void publish()
	{
		snapshot = frame == null ? null : new Snapshot(frame, bounds, fadeInMillis, splats);
	}

	@Value
	static class Snapshot
	{
		BossFrame frame;
		// Min x, max x, min y, max y of the area to fit in the box, in model units.
		float[] bounds;
		long fadeInMillis;
		List<Splat> splats;
	}

	@Value
	static class Splat
	{
		int damage;
		Hit.Type type;
		long millis;
	}
}

package com.idlebosses;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

// The game's health bar and hitsplats, drawn over the mini boss. It isn't a real NPC, so the game can't draw them.
class BossSceneOverlay extends Overlay
{
	private static final long SPLAT_MILLIS = 1200;
	// Like the game, the health bar shows for a while after the last hit.
	private static final long HEALTH_BAR_MILLIS = 6000;
	private static final int HEALTH_BAR_GAP = 18;
	private static final int[][] SPLAT_OFFSETS = BossView.SPLAT_OFFSETS;

	private final Client client;
	private final MiniBoss miniBoss;
	private final SpriteManager spriteManager;
	private final IdleBossesPlugin plugin;

	private final Deque<BossPortrait.Splat> splats = new ArrayDeque<>();
	private final SplatSprites splatSprites;
	private long lastHitMillis;
	private BufferedImage barFront;
	private BufferedImage barBack;

	@Inject
	BossSceneOverlay(Client client, MiniBoss miniBoss, SpriteManager spriteManager, IdleBossesPlugin plugin,
		SplatSprites splatSprites)
	{
		this.splatSprites = splatSprites;
		this.client = client;
		this.miniBoss = miniBoss;
		this.spriteManager = spriteManager;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void addSplat(int damage, Hit.Type type)
	{
		long now = System.currentTimeMillis();
		lastHitMillis = now;
		splats.addLast(new BossPortrait.Splat(damage, type, now));
		while (splats.size() > SPLAT_OFFSETS.length)
		{
			splats.removeFirst();
		}
	}

	void clear()
	{
		splats.clear();
		lastHitMillis = 0;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		LocalPoint location = miniBoss.getLocation();
		if (location == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		int level = miniBoss.getLevel();
		int height = miniBoss.getModelHeight();
		if (now - lastHitMillis < HEALTH_BAR_MILLIS)
		{
			drawHealthBar(graphics, Perspective.localToCanvas(client, location, level, height + HEALTH_BAR_GAP));
		}

		Point middle = Perspective.localToCanvas(client, location, level, height / 2);
		Iterator<BossPortrait.Splat> it = splats.iterator();
		int slot = 0;
		while (it.hasNext())
		{
			BossPortrait.Splat splat = it.next();
			if (now - splat.getMillis() > SPLAT_MILLIS)
			{
				it.remove();
				continue;
			}
			if (middle != null)
			{
				BossView.drawSplat(graphics, splatSprites.get(splat.getType()), splat.getDamage(), middle.getX() + SPLAT_OFFSETS[slot][0],
					middle.getY() + SPLAT_OFFSETS[slot][1]);
			}
			slot++;
		}
		return null;
	}

	private void drawHealthBar(Graphics2D graphics, Point point)
	{
		BossFight fight = plugin.getFight();
		if (point == null || fight.getMaxHp() <= 0)
		{
			return;
		}
		if (barFront == null || barBack == null)
		{
			barFront = spriteManager.getSprite(SpriteID.StandardHealth30.FRONT, 0);
			barBack = spriteManager.getSprite(SpriteID.StandardHealth30.BACK, 0);
			if (barFront == null || barBack == null)
			{
				return;
			}
		}

		int width = barBack.getWidth();
		int barHeight = barBack.getHeight();
		int x = point.getX() - width / 2;
		int y = point.getY() - barHeight / 2;
		int filled = (int) Math.ceil(width * (double) fight.getHp() / fight.getMaxHp());
		graphics.drawImage(barBack, x, y, null);
		if (filled > 0)
		{
			graphics.drawImage(barFront, x, y, x + filled, y + barHeight, 0, 0, filled, barHeight, null);
		}
	}

}

package com.idlebosses;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;

// Draws the boss portrait into a box, for the HUD and the sidebar. Each animation frame is drawn once into an
// image, then that image is reused until the next frame, so a box redrawn every client frame stays cheap.
final class BossView
{
	// Where up to four hitsplats sit around the middle, as in the game.
	static final int[][] SPLAT_OFFSETS = {{0, 0}, {0, -22}, {-16, -11}, {16, -11}};
	private static final long SPLAT_MILLIS = 1200;
	private static final long FADE_IN_MILLIS = 400;
	private static final int PADDING = 6;

	private BufferedImage image;
	private BossFrame drawn;

	// Draws the boss and its hitsplats. Returns true while something is still moving (a hitsplat or a fade in).
	boolean paint(Graphics2D graphics, int x, int y, int width, int height, BossPortrait.Snapshot snapshot, SplatSprites splatSprites)
	{
		if (snapshot == null || snapshot.getFrame() == null || width <= 0 || height <= 0)
		{
			return false;
		}

		if (image == null || image.getWidth() != width || image.getHeight() != height)
		{
			image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			drawn = null;
		}
		if (snapshot.getFrame() != drawn)
		{
			render(snapshot);
			drawn = snapshot.getFrame();
		}

		long now = System.currentTimeMillis();
		long faded = now - snapshot.getFadeInMillis();
		Composite composite = graphics.getComposite();
		if (faded < FADE_IN_MILLIS)
		{
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, (float) faded / FADE_IN_MILLIS)));
		}
		graphics.drawImage(image, x, y, null);
		graphics.setComposite(composite);

		boolean moving = faded < FADE_IN_MILLIS;
		int slot = 0;
		for (BossPortrait.Splat splat : snapshot.getSplats())
		{
			if (now - splat.getMillis() <= SPLAT_MILLIS && slot < SPLAT_OFFSETS.length)
			{
				drawSplat(graphics, splatSprites.get(splat.getType()), splat.getDamage(), x + width / 2 + SPLAT_OFFSETS[slot][0],
					y + height / 2 + SPLAT_OFFSETS[slot][1]);
				slot++;
				moving = true;
			}
		}
		return moving;
	}

	private void render(BossPortrait.Snapshot snapshot)
	{
		BossFrame frame = snapshot.getFrame();
		float[] bounds = snapshot.getBounds();
		int width = image.getWidth();
		int height = image.getHeight();
		float boundsWidth = Math.max(1, bounds[1] - bounds[0]);
		float boundsHeight = Math.max(1, bounds[3] - bounds[2]);
		double scale = Math.min((width - PADDING * 2) / boundsWidth, (height - PADDING * 2) / boundsHeight);
		// Centred across, standing on the bottom of the box.
		double offsetX = width / 2.0 - (bounds[0] + bounds[1]) / 2 * scale;
		double offsetY = height - PADDING - bounds[3] * scale;

		Graphics2D g = image.createGraphics();
		g.setComposite(AlphaComposite.Clear);
		g.fillRect(0, 0, width, height);
		g.setComposite(AlphaComposite.SrcOver);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(0.6f));
		Path2D.Float triangle = new Path2D.Float();
		for (int t = 0; t < frame.triangles; t++)
		{
			triangle.reset();
			triangle.moveTo(offsetX + frame.x[t * 3] * scale, offsetY + frame.y[t * 3] * scale);
			triangle.lineTo(offsetX + frame.x[t * 3 + 1] * scale, offsetY + frame.y[t * 3 + 1] * scale);
			triangle.lineTo(offsetX + frame.x[t * 3 + 2] * scale, offsetY + frame.y[t * 3 + 2] * scale);
			triangle.closePath();
			g.setColor(new Color(frame.rgb[t]));
			g.fill(triangle);
			// Drawing the edge too hides the hairline gaps between triangles.
			g.draw(triangle);
		}
		g.dispose();
	}

	static void drawSplat(Graphics2D graphics, BufferedImage sprite, int damage, int centreX, int centreY)
	{
		if (sprite == null)
		{
			return;
		}
		graphics.drawImage(sprite, centreX - sprite.getWidth() / 2, centreY - sprite.getHeight() / 2, null);
		// Put the font back after, or everything the HUD draws below the boss comes out in the small font.
		Font font = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();
		String text = String.valueOf(damage);
		int textX = centreX - metrics.stringWidth(text) / 2;
		int textY = centreY + metrics.getAscent() / 2 - 1;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, textX + 1, textY + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, textX, textY);
		graphics.setFont(font);
	}
}

package com.idlebosses;

import java.util.Collections;
import java.util.List;
import java.util.Map;

// The drop tables in drops.json, built from the OSRS Wiki by tools/fetch_drops.py. Read with Gson.
final class DropData
{
	String source;
	Map<String, SharedTable> sharedTables = Collections.emptyMap();
	List<BossDrops> bosses = Collections.emptyList();

	BossDrops boss(Boss boss)
	{
		for (BossDrops drops : bosses)
		{
			if (boss.getId().equals(drops.id))
			{
				return drops;
			}
		}
		return null;
	}

	SharedTable table(String name)
	{
		return sharedTables == null ? null : sharedTables.get(name);
	}

	// Gson leaves a list missing from the file as null.
	DropData normalize()
	{
		if (sharedTables == null)
		{
			sharedTables = Collections.emptyMap();
		}
		for (SharedTable table : sharedTables.values())
		{
			table.entries = orEmpty(table.entries);
		}
		bosses = orEmpty(bosses);
		for (BossDrops drops : bosses)
		{
			drops.always = orEmpty(drops.always);
			drops.main = orEmpty(drops.main);
			drops.tables = orEmpty(drops.tables);
			drops.tertiary = orEmpty(drops.tertiary);
			drops.log = orEmpty(drops.log);
		}
		return this;
	}

	private static <T> List<T> orEmpty(List<T> list)
	{
		return list == null ? Collections.emptyList() : list;
	}

	static final class SharedTable
	{
		int outOf;
		List<Drop> entries = Collections.emptyList();
	}

	static final class BossDrops
	{
		String id;
		String name;
		String wikiPage;
		long revision;
		// How many times the main table is rolled each kill.
		int rolls = 1;
		List<Drop> always = Collections.emptyList();
		List<Drop> main = Collections.emptyList();
		int mainOutOf;
		// Weighted slots on the main roll that lead to a shared table, like the rare drop table.
		List<Drop> tables = Collections.emptyList();
		// Independent rolls each kill, like the pet and clue scrolls.
		List<Drop> tertiary = Collections.emptyList();
		// A raid's unique roll, made first: when it hits, its table is rolled once in place of every main roll.
		Drop preRoll;
		// The boss's collection log, in log order.
		List<Integer> log = Collections.emptyList();
	}

	static final class Drop
	{
		int itemId;
		String name;
		int min = 1;
		int max = 1;
		int weight;
		int numerator;
		int denominator;
		boolean noted;
		// Set when this slot rolls a shared table instead of giving an item.
		String table;
	}
}

package com.idlebosses;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

// The chance of getting each item on one kill, counting every way it can drop: the 100% drops,
// each roll of the main table (and the shared tables it leads to), and the tertiary rolls.
final class DropRates
{
	private static final int MAX_TABLE_DEPTH = 3;

	private DropRates()
	{
	}

	static Map<Integer, Double> perKill(DropData data, DropData.BossDrops boss)
	{
		// The chance each route misses the item, multiplied together.
		Map<Integer, Double> miss = new HashMap<>();
		for (DropData.Drop drop : boss.always)
		{
			miss(miss, drop.itemId, 1);
		}

		// The main table is only rolled when a raid's unique roll misses.
		double unique = boss.preRoll == null ? 0 : addSeparateRoll(data, miss, boss.preRoll);
		Map<Integer, Double> perRoll = new HashMap<>();
		addTable(data, perRoll, boss.main, boss.tables, boss.mainOutOf, 1, 0);
		int rolls = Math.max(1, boss.rolls);
		for (Map.Entry<Integer, Double> entry : perRoll.entrySet())
		{
			double hit = (1 - unique) * (1 - Math.pow(1 - entry.getValue(), rolls));
			miss.merge(entry.getKey(), 1 - hit, (a, b) -> a * b);
		}

		for (DropData.Drop drop : boss.tertiary)
		{
			addSeparateRoll(data, miss, drop);
		}

		Map<Integer, Double> chances = new HashMap<>();
		for (Map.Entry<Integer, Double> entry : miss.entrySet())
		{
			chances.put(entry.getKey(), 1 - entry.getValue());
		}
		return chances;
	}

	// "1/3,000", "1/8.6" or "Always".
	static String format(double chance)
	{
		if (chance >= 1 - 1e-9)
		{
			return "Always";
		}
		if (chance <= 0)
		{
			return "Never";
		}
		double kills = 1 / chance;
		if (kills < 10)
		{
			return "1/" + (Math.round(kills * 10) / 10.0);
		}
		return String.format("1/%,d", Math.round(kills));
	}

	// A roll of its own, like a pet or a table it opens. Returns its chance of hitting.
	private static double addSeparateRoll(DropData data, Map<Integer, Double> miss, DropData.Drop drop)
	{
		if (drop.denominator <= 0)
		{
			return 0;
		}
		double chance = (double) drop.numerator / drop.denominator;
		DropData.SharedTable table = drop.table == null ? null : data.table(drop.table);
		if (table != null)
		{
			// One roll on the table when this hits.
			Map<Integer, Double> opened = new HashMap<>();
			addTable(data, opened, table.entries, List.of(), table.outOf, chance, 1);
			for (Map.Entry<Integer, Double> entry : opened.entrySet())
			{
				miss(miss, entry.getKey(), entry.getValue());
			}
		}
		else if (drop.table == null)
		{
			miss(miss, drop.itemId, chance);
		}
		return chance;
	}

	private static void miss(Map<Integer, Double> miss, int itemId, double chance)
	{
		if (itemId > 0)
		{
			miss.merge(itemId, 1 - chance, (a, b) -> a * b);
		}
	}

	// One roll can only give one item, so chances on a roll just add up.
	private static void addTable(DropData data, Map<Integer, Double> perRoll, List<DropData.Drop> entries,
		List<DropData.Drop> tables, int outOf, double chance, int depth)
	{
		if (outOf <= 0)
		{
			return;
		}
		for (List<DropData.Drop> group : List.of(entries, tables))
		{
			for (DropData.Drop drop : group)
			{
				double dropChance = chance * drop.weight / outOf;
				if (drop.table == null)
				{
					if (drop.itemId > 0)
					{
						perRoll.merge(drop.itemId, dropChance, Double::sum);
					}
					continue;
				}
				DropData.SharedTable table = data.table(drop.table);
				if (table != null && depth < MAX_TABLE_DEPTH)
				{
					addTable(data, perRoll, table.entries, List.of(), table.outOf, dropChance, depth + 1);
				}
			}
		}
	}
}

