	@Override
	protected void startUp()
	{
		drops = loadDrops();
		roller = new LootRoller(drops, random);
		rates.clear();

		splatSprites.load(spriteManager);
		panel = new IdleBossesPanel(itemManager, skillIconManager, portrait, splatSprites, () -> cannonLoaded, unreadGuides(),
			new PanelActions());
