	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invoke(() ->
		{
			if (ready)
			{
				loadProgress();
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			ready = false;
			queuedHits.clear();
			miniBoss.set(null, MiniBoss.Variant.NORMAL, config.miniBossSize(), false);
			portrait.clear();
			sceneOverlay.clear();
			pushPanel();
		}
		else if (state == GameState.LOADING)
		{
			// The scene is about to move, which would leave the boss somewhere else. It comes back on the next tick.
			miniBoss.despawn();
			sceneOverlay.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ready)
		{
			// Stats arrive by the first tick after logging in. Before that every skill looks like 0 XP.
			int[] experiences = client.getSkillExperiences();
			System.arraycopy(experiences, 0, xp, 0, Math.min(xp.length, experiences.length));
			ready = true;
			loadProgress();
		}

		miniBoss.gameTick();
		long now = System.currentTimeMillis();
		autoAttacks(now);
		// Anything a huge drop couldn't land in one go.
		if (fight.getPending() > 0)
		{
			landDamage();
		}
		int lost = fight.expireStreak(now);
		if (lost >= STREAK_WORTH_MENTIONING)
		{
			chat(new ChatMessageBuilder().append(ChatColorType.NORMAL)
				.append("Your " + lost + " kill streak ended after a minute without XP."));
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		miniBoss.clientTick();
		portrait.clientTick();
		landQueuedHits(System.currentTimeMillis());
	}

	private void landQueuedHits(long now)
	{
		boolean landed = false;
		for (Iterator<QueuedHit> it = queuedHits.iterator(); it.hasNext(); )
		{
			QueuedHit queued = it.next();
			if (queued.getDueMillis() <= now)
			{
				it.remove();
				showHit(queued.getHit());
				landed = true;
			}
		}
		if (landed)
		{
			miniBoss.hit();
			landDamage();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int index = skill.ordinal();
		if (index >= xp.length)
		{
			return;
		}
		int previous = xp[index];
		xp[index] = event.getXp();
		if (!ready || previous <= 0 || event.getXp() <= previous)
		{
			return;
		}

		int gained = event.getXp() - previous;
		if (SkillRates.xpPerHour(skill) <= 0)
		{
			return;
		}
		lastSkill = skill;
		long base = fight.baseDamage(skill, gained);
		if (base <= 0)
		{
			return;
		}

		long now = System.currentTimeMillis();
		fight.xpGained(now);
		Loadout.Attack attack = loadout.attack(base, fight, random);
		List<Hit> hits = attack.getHits();
		for (int i = 0; i < hits.size(); i++)
		{
			if (i > 0 && i < attack.getStaggered())
			{
				queuedHits.add(new QueuedHit(hits.get(i), now + i * STAGGER_MILLIS));
			}
			else
			{
				showHit(hits.get(i));
			}
		}
		if (attack.getSpecial() != null)
		{
			special = new Special(loadout.weapon(), attack.getSpecial(), now);
		}
		miniBoss.hit();
		landDamage();
	}

	// The cannon and poison, which keep hitting while you train.
	private void autoAttacks(long now)
	{
		Boss boss = fight.getBoss();
		if (!ready || boss == null || !fight.isActive(now))
		{
			return;
		}
		Progress.CannonState cannon = progress.cannon;
		cannonTicks = Math.min(cannonTicks + 1, Shop.CANNON_FIRE_TICKS);
		if (cannon.loaded > 0 && cannonTicks >= Shop.CANNON_FIRE_TICKS)
		{
			cannonTicks = 0;
			int before = cannon.loaded;
			Hit shot = Shop.fire(progress, boss, loadout.cannonballSaveChance(), random);
			if (shot != null)
			{
				showHit(shot);
				if (cannon.loaded == before)
				{
					special = new Special(Gear.KODAI_WAND, "Saved", now);
				}
				cannonLoaded = cannon.loaded;
				if (cannon.loaded == 0)
				{
					chat(new ChatMessageBuilder().append(ChatColorType.NORMAL).append("Your cannon is out of ammo!"));
				}
			}
		}
		if (fight.isPoisoned() && now - lastPoisonMillis >= POISON_MILLIS)
		{
			lastPoisonMillis = now;
			showHit(new Hit(Loadout.poisonDamage(boss), Hit.Type.POISON));
		}
	}

	// Adds a hit's damage and shows its splat. It lands with the next landDamage().
	private void showHit(Hit hit)
	{
		fight.addDamage(hit.getDamage());
		int shown = (int) Math.min(Integer.MAX_VALUE, hit.getDamage());
		sceneOverlay.addSplat(shown, hit.getType());
		portrait.hit(shown, hit.getType());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (IdleBossesConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(this::showMiniBoss);
		}
	}

	// "Dropped at KC 41", naming the boss when it came from another one, or null if it wasn't kept.
	private static String dropped(Boss boss, Progress.LogDrop drop)
	{
		if (drop == null)
		{
			return null;
		}
		Boss from = Boss.byId(drop.boss);
		String kc = "KC " + QuantityFormatter.formatNumber(drop.kills);
		return from == null || from == boss ? "Dropped at " + kc : "Dropped by " + from.getDisplayName() + " at " + kc;
	}

	// The boss's collection log, in the game's order.
	List<Integer> logItems(Boss boss)
	{
		DropData.BossDrops bossDrops = drops == null ? null : drops.boss(boss);
		return bossDrops == null ? Collections.emptyList() : bossDrops.log;
	}

	boolean isLogComplete(Boss boss)
	{
		DropData.BossDrops bossDrops = drops.boss(boss);
		return bossDrops != null && !bossDrops.log.isEmpty() && progress.logCount(bossDrops.log) >= bossDrops.log.size();
	}

	// Lands the damage waiting in the fight. One big drop can kill several bosses in a row; each rolls its loot.
	private void landDamage()
	{
		KillRun run = null;
		while (run == null || run.kills < MAX_KILLS_PER_TICK)
		{
			Boss boss = fight.getBoss();
			boolean killed = fight.land(loadout.executeBelow());
			long executed = fight.takeExecuted();
			if (executed > 0)
			{
				// The Voidwaker's finishing blow.
				int shown = (int) Math.min(Integer.MAX_VALUE, executed);
				sceneOverlay.addSplat(shown, Hit.Type.CRITICAL);
				portrait.hit(shown, Hit.Type.CRITICAL);
				special = new Special(Gear.VOIDWAKER, "Finished", System.currentTimeMillis());
			}
			if (!killed)
			{
				break;
			}
			if (run == null)
			{
				run = new KillRun(boss, unlockedBosses(), isLogComplete(boss));
			}
			kill(run);
		}
		if (run != null)
		{
			finishKills(run);
		}
	}

	private void kill(KillRun run)
	{
		Boss boss = fight.getBoss();
		DropData.BossDrops bossDrops = drops.boss(boss);
		boolean superior = fight.isSuperior();
		progress.addKill(boss);
		run.kills++;
		run.superiors += superior ? 1 : 0;

		List<Loot> loot = bossDrops == null ? Collections.emptyList() : roller.roll(bossDrops, superior);
		Set<Integer> logIds = bossDrops == null ? Collections.emptySet() : new LinkedHashSet<>(bossDrops.log);
		for (Loot item : loot)
		{
			run.value += itemManager.getItemPrice(item.getItemId()) * (long) item.getQuantity();
			progress.addLoot(boss, item.getItemId(), item.getQuantity());
			if (!logIds.contains(item.getItemId()) || !progress.addLogItem(item.getItemId(), boss))
			{
				continue;
			}
			run.newLogItems.add(item.getItemId());
			double chance = rates(boss).getOrDefault(item.getItemId(), item.getChance());
			boolean rareItem = chance <= Loot.RARE_CHANCE;
			run.rare |= rareItem;
			chat(new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append("New collection log item: ")
				.append(rareItem ? RARE_COLOR : CHAT_TAG_COLOR, item.getName())
				.append(ChatColorType.NORMAL)
				.append(" (" + DropRates.format(chance) + ")"));
		}
		run.loot.addAll(loot);

		fight.start(boss, random.nextInt(SUPERIOR_CHANCE) == 0);
	}

	private void finishKills(KillRun run)
	{
		Boss boss = run.boss;
		progress.addLootValue(run.value);
		showLoot(LootRoller.merge(run.loot), run.newLogItems);

		String what = run.kills == 1 && run.superiors == 1 ? "superior " + boss.getDisplayName() : boss.getDisplayName();
		String extra = "";
		if (run.kills > 1)
		{
			extra = " (" + run.kills + " kills from one XP drop"
				+ (run.superiors > 0 ? ", " + run.superiors + " of them superior" : "") + ")";
		}
		chat(new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("Your " + what + " kill count is: ")
			.append(Color.RED, String.valueOf(progress.kills(boss)))
			.append(ChatColorType.NORMAL)
			.append("." + extra));

		if (run.rare)
		{
			celebrate();
		}
		if (!run.logCompleteBefore && isLogComplete(boss))
		{
			chat(new ChatMessageBuilder()
				.append(ChatColorType.NORMAL)
				.append(boss.getDisplayName() + " collection log complete. Your " + boss.getDisplayName() + " is gold now."));
		}
		for (Boss unlocked : Boss.values())
		{
			if (!run.unlockedBefore.contains(unlocked) && progress.isUnlocked(unlocked))
			{
				chat(new ChatMessageBuilder()
					.append(GOOD_COLOR, unlocked.getDisplayName() + " unlocked!")
					.append(ChatColorType.NORMAL)
					.append(" Pick it in the Idle Bosses panel."));
			}
		}

		Boss next = fight.getBoss();
		MiniBoss.Variant variant = variant(next, fight.isSuperior());
		miniBoss.kill(next, variant);
		portrait.kill(next, variant);
		if (fight.isSuperior())
		{
			chat(new ChatMessageBuilder().append(RARE_COLOR, "A superior " + next.getDisplayName() + " has appeared!"));
		}

		saveProgress();
		pushPanel();
	}

	// A weapon effect that triggered, and when.
	@Value
	static class Special
	{
		Gear weapon;
		// What it did, like "x4".
		String label;
		long millis;
	}

	@Value
	private static class QueuedHit
	{
		Hit hit;
		long dueMillis;
	}

	// The kills one landing of damage caused, gathered so chat and the HUD show them together.
	private static final class KillRun
	{
		final Boss boss;
		final Set<Boss> unlockedBefore;
		final boolean logCompleteBefore;
		final List<Loot> loot = new ArrayList<>();
		final Set<Integer> newLogItems = new LinkedHashSet<>();
		int kills;
		int superiors;
		long value;
		boolean rare;

		KillRun(Boss boss, Set<Boss> unlockedBefore, boolean logCompleteBefore)
		{
			this.boss = boss;
			this.unlockedBefore = unlockedBefore;
			this.logCompleteBefore = logCompleteBefore;
		}
	}

	private Set<Boss> unlockedBosses()
	{
		Set<Boss> unlocked = EnumSet.noneOf(Boss.class);
		for (Boss boss : Boss.values())
		{
			if (progress.isUnlocked(boss))
			{
				unlocked.add(boss);
			}
		}
		return unlocked;
	}

	private void showLoot(List<Loot> loot, Set<Integer> newLogItems)
	{
		Set<Integer> rare = new HashSet<>();
		for (Loot item : loot)
		{
			if (newLogItems.contains(item.getItemId()) && item.isRare())
			{
				rare.add(item.getItemId());
			}
		}
		lastLogItems = newLogItems;
		lastRareLogItems = rare;
	}

	// The level-up fireworks and a ding, for a pet or a rare log item.
	private void celebrate()
	{
		Player player = client.getLocalPlayer();
		if (player != null)
		{
			player.createSpotAnim(FIREWORKS_SLOT, SpotanimID.LEVELUP_ANIM, 0, 0);
		}
		if (config.rareDropSound())
		{
			client.playSoundEffect(SoundEffectID.GE_ADD_OFFER_DINGALING);
		}
	}

	private void switchBoss(Boss boss)
	{
		if (!ready || !progress.isUnlocked(boss) || boss == fight.getBoss())
		{
			return;
		}
		progress.currentBoss = boss.getId();
		fight.start(boss, false);
		sceneOverlay.clear();
		showMiniBoss();
		saveProgress();
		pushPanel();
	}

	private void startCurrentBoss()
	{
		Boss boss = Boss.byId(progress.currentBoss);
		if (boss == null || !progress.isUnlocked(boss) || drops.boss(boss) == null)
		{
			boss = Boss.values()[0];
		}
		progress.currentBoss = boss.getId();
		fight.start(boss, false);
	}

	// Shows the current boss in the HUD and sidebar, and walking in the world if that's turned on.
	private void showMiniBoss()
	{
		Boss boss = fight.getBoss();
		MiniBoss.Variant variant = boss == null ? MiniBoss.Variant.NORMAL : variant(boss, fight.isSuperior());
		miniBoss.set(boss, variant, config.miniBossSize(), ready && config.showMiniBoss());
		if (ready && boss != null)
		{
			portrait.set(boss, variant);
		}
		else
		{
			portrait.clear();
		}
	}

	private MiniBoss.Variant variant(Boss boss, boolean superior)
	{
		if (superior)
		{
			return MiniBoss.Variant.SUPERIOR;
		}
		return isLogComplete(boss) ? MiniBoss.Variant.GOLD : MiniBoss.Variant.NORMAL;
	}

	private void chat(ChatMessageBuilder message)
	{
		if (!config.chatMessages())
		{
			return;
		}
		String text = new ChatMessageBuilder()
			.append(CHAT_TAG_COLOR, "[Idle Bosses] ")
			.build() + message.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(text)
			.build());
	}

	private void loadProgress()
	{
		String json = configManager.getRSProfileConfiguration(IdleBossesConfig.GROUP, PROGRESS_KEY);
		Progress loaded = null;
		if (json != null)
		{
			try
			{
				loaded = gson.fromJson(json, Progress.class);
				loaded = loaded == null ? null : loaded.migrate();
			}
			catch (JsonParseException e)
			{
				log.warn("Couldn't read saved Idle Bosses progress", e);
			}
		}
		progress = loaded != null ? loaded : new Progress().migrate();
		progressProfile = configManager.getRSProfileKey();
		loadout = Loadout.of(progress);
		cannonLoaded = progress.cannon.loaded;
		fight.clearPending();
		queuedHits.clear();
		special = null;
		startCurrentBoss();
		lastLogItems = Collections.emptySet();
		lastRareLogItems = Collections.emptySet();
		sceneOverlay.clear();
		if (ready)
		{
			showMiniBoss();
		}
		pushPanel();
	}

	private void saveProgress()
	{
		// Never write one account's progress over another's.
		String profile = configManager.getRSProfileKey();
		if (profile == null || !profile.equals(progressProfile))
		{
			return;
		}
		configManager.setRSProfileConfiguration(IdleBossesConfig.GROUP, PROGRESS_KEY, gson.toJson(progress));
	}

	private void pushPanel()
	{
		IdleBossesPanel target = panel;
		if (target == null)
		{
			return;
		}
		IdleBossesPanel.State state = ready ? panelState() : null;
		SwingUtilities.invokeLater(() -> target.setState(state));
	}

	private IdleBossesPanel.State panelState()
	{
		List<IdleBossesPanel.Row> rows = new ArrayList<>();
		for (Boss boss : Boss.values())
		{
			DropData.BossDrops bossDrops = drops.boss(boss);
			if (bossDrops == null)
			{
				continue;
			}
			Map<Integer, String> names = itemNames(bossDrops);
			List<IdleBossesPanel.LogItem> log = new ArrayList<>();
			Set<Integer> owned = new LinkedHashSet<>();
			for (int itemId : bossDrops.log)
			{
				log.add(new IdleBossesPanel.LogItem(itemId, names.getOrDefault(itemId, "Unknown item"),
					rates(boss).getOrDefault(itemId, 0.0), dropped(boss, progress.logDrop(itemId))));
				if (progress.hasLogItem(itemId))
				{
					owned.add(itemId);
				}
			}

			List<IdleBossesPanel.LootItem> loot = new ArrayList<>();
			for (Map.Entry<Integer, Long> entry : progress.loot(boss).entrySet())
			{
				int itemId = entry.getKey();
				long quantity = entry.getValue();
				loot.add(new IdleBossesPanel.LootItem(itemId, names.getOrDefault(itemId, "Unknown item"), quantity,
					itemManager.getItemPrice(itemId) * quantity));
			}
			// Most valuable first, like the loot tracker.
			loot.sort(Comparator.comparingLong(IdleBossesPanel.LootItem::getValue).reversed()
				.thenComparing(Comparator.comparingLong(IdleBossesPanel.LootItem::getQuantity).reversed()));
			int icon = bossDrops.log.isEmpty() ? -1 : bossDrops.log.get(0);
			rows.add(new IdleBossesPanel.Row(boss, icon, progress.isUnlocked(boss), boss == fight.getBoss(),
				progress.kills(boss), boss.previous() == null ? 0 : progress.kills(boss.previous()), log, owned, loot));
		}
		return new IdleBossesPanel.State(rows, progress.totalKills(), progress.totalSlots(), progress.gpLooted, upgradesState());
	}

	private IdleBossesPanel.Upgrades upgradesState()
	{
		Loadout worn = Loadout.of(progress);
		Gear amulet = progress.best(Gear.Slot.AMULET);
		Gear gloves = progress.best(Gear.Slot.GLOVES);
		List<IdleBossesPanel.GearRow> gear = new ArrayList<>();
		for (Gear item : Gear.values())
		{
			List<String> needs = new ArrayList<>();
			for (int itemId : Shop.missing(progress, item))
			{
				needs.add(itemManager.getItemComposition(itemId).getName());
			}
			Gear previous = item.previousTier();
			boolean active = item == amulet || item == gloves || worn.wields(item);
			gear.add(new IdleBossesPanel.GearRow(item, progress.owns(item), active, Shop.canBuy(progress, item),
				previous == null || progress.owns(previous), needs.isEmpty() ? null : String.join(", ", needs)));
		}
		Progress.CannonState cannon = progress.cannon;
		return new IdleBossesPanel.Upgrades(progress.coins(), gear,
			new IdleBossesPanel.CannonRow(cannon.owned, cannon.cannonballs, cannon.granite));
	}

	// After anything bought, wielded or loaded.
	private void changedUpgrades()
	{
		loadout = Loadout.of(progress);
		cannonLoaded = progress.cannon.loaded;
		saveProgress();
		pushPanel();
	}

	private void reloadCannon()
	{
		if (ready && Shop.reload(progress) > 0)
		{
			changedUpgrades();
		}
	}

	// The sidebar tabs whose guide hasn't been read. Kept per RuneLite profile, not per account, since it's the person
	// who has read it.
	private Set<IdleBossesPanel.Guide> unreadGuides()
	{
		Set<IdleBossesPanel.Guide> unread = EnumSet.noneOf(IdleBossesPanel.Guide.class);
		for (IdleBossesPanel.Guide guide : IdleBossesPanel.Guide.values())
		{
			if (!Boolean.TRUE.equals(configManager.getConfiguration(IdleBossesConfig.GROUP, guideKey(guide), Boolean.class)))
			{
				unread.add(guide);
			}
		}
		return unread;
	}

	private static String guideKey(IdleBossesPanel.Guide guide)
	{
		return guide == IdleBossesPanel.Guide.FIGHT ? FIGHT_GUIDE_KEY : UPGRADES_GUIDE_KEY;
	}

	// The sidebar's buttons. The game ones run on the client thread.
	private final class PanelActions implements IdleBossesPanel.Actions
	{
		@Override
		public void readGuide(IdleBossesPanel.Guide guide)
		{
			configManager.setConfiguration(IdleBossesConfig.GROUP, guideKey(guide), true);
		}

		@Override
		public void fight(Boss boss)
		{
			clientThread.invoke(() -> switchBoss(boss));
		}

		@Override
		public void buy(Gear gear)
		{
			clientThread.invoke(() ->
			{
				if (ready && Shop.buy(progress, gear))
				{
					changedUpgrades();
				}
			});
		}

		@Override
		public void wield(Gear gear)
		{
			clientThread.invoke(() ->
			{
				if (ready && Shop.wield(progress, gear))
				{
					changedUpgrades();
				}
			});
		}

		@Override
		public void buyCannon()
		{
			clientThread.invoke(() ->
			{
				if (ready && Shop.buyCannon(progress))
				{
					changedUpgrades();
				}
			});
		}

		@Override
		public void buyCannonballs(boolean granite)
		{
			clientThread.invoke(() ->
			{
				if (ready && Shop.buyCannonballs(progress, granite))
				{
					changedUpgrades();
				}
			});
		}

		@Override
		public void reloadCannon()
		{
			clientThread.invoke(IdleBossesPlugin.this::reloadCannon);
		}
	}

	private Map<Integer, Double> rates(Boss boss)
	{
		return rates.computeIfAbsent(boss, b ->
		{
			DropData.BossDrops bossDrops = drops.boss(b);
			return bossDrops == null ? Collections.emptyMap() : DropRates.perKill(drops, bossDrops);
		});
	}

	private Map<Integer, String> itemNames(DropData.BossDrops bossDrops)
	{
		Map<Integer, String> names = new HashMap<>();
		List<List<DropData.Drop>> groups = new ArrayList<>(List.of(bossDrops.always, bossDrops.main, bossDrops.tertiary));
		for (DropData.SharedTable table : drops.sharedTables.values())
		{
			groups.add(table.entries);
		}
		for (List<DropData.Drop> group : groups)
		{
			for (DropData.Drop drop : group)
			{
				if (drop.itemId > 0 && drop.name != null)
				{
					names.putIfAbsent(drop.itemId, drop.name);
				}
			}
		}
		return names;
	}

	private DropData loadDrops()
	{
		try (InputStream in = getClass().getResourceAsStream(DROPS_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Idle Bosses drop tables are missing");
				return new DropData();
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				DropData data = gson.fromJson(reader, DropData.class);
				return data == null ? new DropData() : data.normalize();
			}
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Couldn't read the Idle Bosses drop tables", e);
			return new DropData().normalize();
		}
	}
}

package com.idlebosses;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import lombok.Value;

// What you're wearing and wielding, and how it turns an XP drop's damage into hits. Pure, so it can be tested.
final class Loadout
{
	// From the bosses' Wiki attributes, for the dragon hunter crossbow and Arclight. A run counts by its final boss.
	static final Set<Boss> DRAGONS = EnumSet.of(Boss.KING_BLACK_DRAGON, Boss.VORKATH, Boss.ALCHEMICAL_HYDRA,
		Boss.HUEYCOATL, Boss.CHAMBERS_OF_XERIC);
	static final Set<Boss> DEMONS = EnumSet.of(Boss.ABYSSAL_SIRE, Boss.CERBERUS, Boss.DOOM_OF_MOKHAIOTL,
		Boss.DUKE_SUCELLUS, Boss.KRIL_TSUTSAROTH, Boss.SKOTIZO, Boss.YAMA, Boss.FRACTURED_ARCHIVE);
	static final double SANGUINESTI_CHANCE = 1 / 6.0;
	private static final double[] CLAW_HITS = {1, 0.5, 0.25, 0.25};
	private static final double[] SCYTHE_HITS = {1, 0.5, 0.25};
	private static final double[] DOUBLE_HIT = {1, 1};
	private static final double[] ONE_HIT = {1};

	private final Gear amulet;
	private final Gear gloves;
	private final Gear weapon;

	Loadout(Gear amulet, Gear gloves, Gear weapon)
	{
		this.amulet = amulet;
		this.gloves = gloves;
		this.weapon = weapon;
	}

	static Loadout of(Progress progress)
	{
		return new Loadout(progress.best(Gear.Slot.AMULET), progress.best(Gear.Slot.GLOVES), progress.wielded());
	}

	boolean wields(Gear gear)
	{
		return weapon == gear;
	}

	Gear weapon()
	{
		return weapon;
	}

	// The amulet's damage bonus, as a fraction.
	double amuletBonus()
	{
		double bonus = amulet == null ? 0 : amulet.getValue() / 100.0;
		return wields(Gear.TUMEKENS_SHADOW) ? bonus * Gear.TUMEKENS_SHADOW.getValue() : bonus;
	}

	// The health a boss is finished at, as a fraction of its maximum. 0 without the Voidwaker.
	double executeBelow()
	{
		return wields(Gear.VOIDWAKER) ? Gear.VOIDWAKER.getValue() / 100.0 : 0;
	}

	double cannonballSaveChance()
	{
		return wields(Gear.KODAI_WAND) ? Gear.KODAI_WAND.getValue() / 100.0 : 0;
	}

	// One XP drop's hits, and what the weapon's effect did if it triggered.
	@Value
	static class Attack
	{
		List<Hit> hits;
		// The first this many hits are one special's, landing a beat apart. 1 for a normal drop.
		int staggered;
		// What the effect did, for the HUD's banner, like "x4" for the claws' four hits. Null when nothing triggered.
		String special;
	}

	// The hits one XP drop makes. The fight is told about hits on its boss, for the Soulreaper axe and poison.
	Attack attack(long base, BossFight fight, Random random)
	{
		List<Hit> hits = new ArrayList<>();
		Boss boss = fight.getBoss();
		if (base <= 0 || boss == null)
		{
			return new Attack(hits, 0, null);
		}

		String special = null;
		double damage = base * (1 + amuletBonus()) * (1 + weaponBonus(boss, fight.getHitsOnBoss()));
		Hit.Type type = Hit.Type.NORMAL;
		double critChance = gloves == null ? 0 : gloves.getValue() / 100.0;
		boolean crit = random.nextDouble() < critChance;
		// Osmumten's fang gets a second try.
		if (!crit && wields(Gear.OSMUMTENS_FANG) && random.nextDouble() < critChance)
		{
			crit = true;
			special = "Second roll";
		}
		if (crit)
		{
			type = Hit.Type.CRITICAL;
			if (wields(Gear.ARMADYL_CROSSBOW))
			{
				damage *= Gear.ARMADYL_CROSSBOW.getValue();
				special = "x" + Gear.ARMADYL_CROSSBOW.getValue();
			}
			else
			{
				damage *= 2;
			}
		}
		if (wields(Gear.SANGUINESTI_STAFF) && random.nextDouble() < SANGUINESTI_CHANCE)
		{
			damage *= 1 + Gear.SANGUINESTI_STAFF.getValue() / 100.0;
			special = "+" + Gear.SANGUINESTI_STAFF.getValue() + "%";
		}

		double[] split = split(random);
		if (split.length > 1)
		{
			special = "x" + split.length;
		}
		for (double share : split)
		{
			hits.add(new Hit(Math.max(1, Math.round(damage * share)), type));
		}
		if (wields(Gear.TOXIC_BLOWPIPE))
		{
			hits.add(new Hit(Math.max(1, Math.round(Gear.TOXIC_BLOWPIPE.getValue() * boss.damageScale())), Hit.Type.DART));
		}
		if (wields(Gear.ABYSSAL_TENTACLE) && !fight.isPoisoned() && random.nextInt(100) < Gear.ABYSSAL_TENTACLE.getValue())
		{
			fight.poison();
			special = "Poisoned";
		}
		fight.addHitOnBoss();
		return new Attack(hits, split.length, special);
	}

	// A poison tick: about 5% of what you'd deal in the same time at a typical pace.
	static long poisonDamage(Boss boss)
	{
		return Math.max(1, Math.round(boss.damageScale()));
	}

	private double weaponBonus(Boss boss, int hitsOnBoss)
	{
		if (weapon == null)
		{
			return 0;
		}
		switch (weapon)
		{
			case DRAGON_SCIMITAR:
				return weapon.getValue() / 100.0;
			case ARCLIGHT:
				return DEMONS.contains(boss) ? weapon.getValue() / 100.0 : 0;
			case DRAGON_HUNTER_CROSSBOW:
				return DRAGONS.contains(boss) ? weapon.getValue() / 100.0 : 0;
			case SOULREAPER_AXE:
				return Math.min(hitsOnBoss, weapon.getValue()) / 100.0;
			case TWISTED_BOW:
				// +1% for each point of toughness: 1% on Obor, about 8% on the Nightmare.
				return Math.min(boss.damageScale(), weapon.getValue()) / 100.0;
			default:
				return 0;
		}
	}

	// How the drop's damage is shared across its hits.
	private double[] split(Random random)
	{
		if (wields(Gear.DRAGON_CLAWS) && random.nextInt(Gear.DRAGON_CLAWS.getValue()) == 0)
		{
			return CLAW_HITS;
		}
		if (wields(Gear.SCYTHE_OF_VITUR) && random.nextInt(100) < Gear.SCYTHE_OF_VITUR.getValue())
		{
			return SCYTHE_HITS;
		}
		if (wields(Gear.MAGIC_SHORTBOW) && random.nextInt(100) < Gear.MAGIC_SHORTBOW.getValue())
		{
			return DOUBLE_HIT;
		}
		return ONE_HIT;
	}
}

package com.idlebosses;

import lombok.Value;

@Value
class Loot
{
	// Pets and log items rarer than this get the fanfare.
	static final double RARE_CHANCE = 1.0 / 100;

	int itemId;
	String name;
	int quantity;
	// The chance of the roll that gave this drop. DropRates has the chance of the item on a whole kill.
	double chance;

	boolean isRare()
	{
		return chance <= RARE_CHANCE;
	}
}

package com.idlebosses;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

// Rolls a kill's loot the way the game does: the 100% drops, a raid's unique roll, the main table (sometimes
// more than once, and not at all when the raid's unique hits), then each tertiary roll on its own.
final class LootRoller
{
	// The rare drop table can point at the gem table, so allow a couple of levels.
	private static final int MAX_TABLE_DEPTH = 3;

	private final DropData data;
	private final Random random;

	LootRoller(DropData data, Random random)
	{
		this.data = data;
		this.random = random;
	}

	// A superior gets one extra roll on the main table.
	List<Loot> roll(DropData.BossDrops boss, boolean superior)
	{
		List<Loot> loot = new ArrayList<>();
		for (DropData.Drop drop : boss.always)
		{
			add(loot, drop, 1);
		}

		// A raid's unique takes the place of its common rolls.
		boolean unique = boss.preRoll != null && rollSeparately(loot, boss.preRoll);
		int rolls = (unique ? 0 : Math.max(1, boss.rolls)) + (superior ? 1 : 0);
		for (int i = 0; i < rolls; i++)
		{
			rollTable(loot, boss.main, boss.tables, boss.mainOutOf, 1, 0);
		}

		for (DropData.Drop drop : boss.tertiary)
		{
			rollSeparately(loot, drop);
		}
		return merge(loot);
	}

	// One roll of its own at the drop's chance. Returns whether it hit.
	private boolean rollSeparately(List<Loot> loot, DropData.Drop drop)
	{
		if (drop.denominator <= 0 || random.nextInt(drop.denominator) >= drop.numerator)
		{
			return false;
		}
		double chance = (double) drop.numerator / drop.denominator;
		DropData.SharedTable table = drop.table == null ? null : data.table(drop.table);
		if (table != null)
		{
			// A separate roll that opens a table, like Abyssal Sire's Unsired at the Font of Consumption.
			rollTable(loot, table.entries, List.of(), table.outOf, chance, 1);
		}
		else if (drop.table == null)
		{
			add(loot, drop, chance);
		}
		return true;
	}

	private void rollTable(List<Loot> loot, List<DropData.Drop> entries, List<DropData.Drop> tables, int outOf, double chance, int depth)
	{
		if (outOf <= 0)
		{
			return;
		}

		int roll = random.nextInt(outOf);
		for (List<DropData.Drop> group : List.of(entries, tables))
		{
			for (DropData.Drop drop : group)
			{
				if (roll >= drop.weight)
				{
					roll -= drop.weight;
					continue;
				}

				double dropChance = chance * drop.weight / outOf;
				if (drop.table == null)
				{
					add(loot, drop, dropChance);
					return;
				}

				DropData.SharedTable table = data.table(drop.table);
				if (table != null && depth < MAX_TABLE_DEPTH)
				{
					rollTable(loot, table.entries, List.of(), table.outOf, dropChance, depth + 1);
				}
				return;
			}
		}
		// What's left of the weights is a roll that gives nothing.
	}

	private void add(List<Loot> loot, DropData.Drop drop, double chance)
	{
		if (drop.itemId <= 0)
		{
			return;
		}
		int min = Math.max(1, drop.min);
		int quantity = min + random.nextInt(Math.max(min, drop.max) - min + 1);
		loot.add(new Loot(drop.itemId, drop.name, quantity, chance));
	}

	// Two rolls of the same item show as one stack, keeping the rarer chance.
	static List<Loot> merge(List<Loot> loot)
	{
		Map<Integer, Loot> merged = new LinkedHashMap<>();
		for (Loot item : loot)
		{
			merged.merge(item.getItemId(), item, (a, b) ->
				new Loot(a.getItemId(), a.getName(), a.getQuantity() + b.getQuantity(), Math.min(a.getChance(), b.getChance())));
		}
		return new ArrayList<>(merged.values());
	}
}

package com.idlebosses;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.AnimationID;

// The small boss next to the player. It's a client-side model: it can't be clicked and nobody else sees it.
// It walks after the player along the tiles they've walked, so it doesn't cut through walls, and only jumps
// to them when they teleport or change floor. Only used on the client thread.
@Singleton
class MiniBoss
{
	enum Variant
	{
		NORMAL,
		SUPERIOR,
		// The boss's collection log is complete.
		GOLD
	}

	// The model of the game's smoke puff (SpotanimID.SMOKEPUFF). There are no gameval constants for models.
	private static final int SMOKE_PUFF_MODEL = 3076;
	private static final int MODEL_SCALE_UNIT = 128;
	private static final int RESPAWN_DELAY_CYCLES = 30;
	// Walking pace is a tile a game tick, which is 30 client cycles. It speeds up to catch a running player.
	private static final double WALK_SPEED = (double) Perspective.LOCAL_TILE_SIZE / 30;
	private static final double MAX_SPEED = WALK_SPEED * 3;
	private static final double CATCH_UP_CYCLES = 30;
	// Turning speed in 2048ths of a turn a client cycle, close to an NPC's.
	private static final int TURN_SPEED = 32;
	// The player moving further than this in one tick is a teleport, not a walk or a run.
	private static final int TELEPORT_TILES = 3;
	private static final int MAX_DISTANCE_TILES = 10;
	private static final int MAX_TRAIL = 32;
	private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
	// Two tiles out so the boss doesn't stand inside the player, then closer if those are blocked.
	private static final int[][] SPAWN_OFFSETS = {
		{2, 0}, {0, -2}, {-2, 0}, {0, 2}, {2, -1}, {2, 1}, {-2, -1}, {-2, 1},
		{1, -2}, {-1, -2}, {1, 2}, {-1, 2}, {1, 0}, {0, -1}, {-1, 0}, {0, 1},
	};

	private final Client client;

	private RuneLiteObject object;
	private RuneLiteObject puff;

	private Boss boss;
	private Variant variant = Variant.NORMAL;
	private MiniBossSize size = MiniBossSize.SMALL;
	private boolean enabled;

	private boolean dying;
	private boolean spawning;
	private boolean walking;
	private int hideAtCycle = -1;
	private int spawnAtCycle = -1;
	private int lastCycle;
	// The boss height above its tile, for drawing the health bar and hitsplats.
	@Getter
	private int modelHeight;

	// Exact position, so slow movement isn't lost to rounding.
	private double x;
	private double y;
	private int orientation;
	// The tiles the player has walked, oldest first. The boss walks to the one a few steps behind them.
	private final Deque<LocalPoint> trail = new ArrayDeque<>();
	private LocalPoint target;

	@Inject
	MiniBoss(Client client)
	{
		this.client = client;
	}

	// Shows this boss, replacing any other. Pass enabled false to keep it hidden.
	void set(Boss boss, Variant variant, MiniBossSize size, boolean enabled)
	{
		boolean changed = boss != this.boss || variant != this.variant || size != this.size;
		this.boss = boss;
		this.variant = variant;
		this.size = size;
		this.enabled = enabled;
		if (!enabled || boss == null)
		{
			despawn();
		}
		else if (changed || !isVisible())
		{
			despawn();
			spawn();
		}
	}

	// The boss died: play its death, then bring in the next one.
	void kill(Boss next, Variant nextVariant)
	{
		Boss dead = boss;
		boss = next;
		variant = nextVariant;
		// Hidden: the next boss appears on the next tick. Already dying: the respawn shows the new one.
		if (!isVisible() || dying || dead == null)
		{
			return;
		}

		dying = true;
		spawning = false;
		walking = false;
		target = null;
		Animation death = client.loadAnimation(dead.getDeathAnimation());
		hideAtCycle = client.getGameCycle() + BossModels.deathCycles(death);
		playOnce(death, this::finishDeath);
	}

	void hit()
	{
		// A flinch would cut the spawn animation short, and freeze the legs mid-walk.
		if (isAlive() && !spawning && !walking && boss.getDefendAnimation() != -1)
		{
			playOnce(client.loadAnimation(boss.getDefendAnimation()), this::pose);
		}
	}

	void clientTick()
	{
		int cycle = client.getGameCycle();
		int cycles = Math.max(1, Math.min(10, cycle - lastCycle));
		lastCycle = cycle;

		if (dying && cycle >= hideAtCycle)
		{
			finishDeath();
		}
		if (spawnAtCycle >= 0 && cycle >= spawnAtCycle)
		{
			spawnAtCycle = -1;
			spawn();
		}
		if (isAlive())
		{
			move(cycles);
		}
	}

	void gameTick()
	{
		Player player = client.getLocalPlayer();
		if (!enabled || boss == null || player == null)
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		LocalPoint here = player.getLocalLocation();
		if (!isVisible())
		{
			if (!dying && spawnAtCycle < 0)
			{
				spawn();
			}
			return;
		}
		if (dying || here == null)
		{
			return;
		}

		LocalPoint last = trail.peekLast();
		boolean teleported = last != null && tiles(last, here) > TELEPORT_TILES;
		if (player.getWorldView() != worldView || object.getLevel() != worldView.getPlane() || teleported
			|| tiles(object.getLocation(), here) > MAX_DISTANCE_TILES)
		{
			// Teleports, ladders and boats: take the boss away and bring it in next to the player.
			despawn();
			spawn();
			return;
		}

		if (last == null || last.getSceneX() != here.getSceneX() || last.getSceneY() != here.getSceneY())
		{
			trail.addLast(here);
			while (trail.size() > MAX_TRAIL)
			{
				trail.removeFirst();
			}
		}

		// The tile the player stood on a few steps ago, so the boss trails behind without crowding them.
		int behind = followSteps();
		if (trail.size() > behind)
		{
			Iterator<LocalPoint> it = trail.descendingIterator();
			for (int i = 0; i < behind; i++)
			{
				it.next();
			}
			target = it.next();
		}
	}

	// Takes the models out of the scene. They come back on the next tick.
	void despawn()
	{
		dying = false;
		spawning = false;
		walking = false;
		hideAtCycle = -1;
		spawnAtCycle = -1;
		target = null;
		trail.clear();
		if (object != null)
		{
			object.setActive(false);
		}
		if (puff != null)
		{
			puff.setActive(false);
		}
	}

	void shutDown()
	{
		despawn();
		enabled = false;
		boss = null;
		object = null;
		puff = null;
	}

	boolean isAlive()
	{
		return isVisible() && !dying;
	}

	LocalPoint getLocation()
	{
		return isAlive() ? object.getLocation() : null;
	}

	int getLevel()
	{
		return object == null ? 0 : object.getLevel();
	}

	private boolean isVisible()
	{
		return object != null && object.isActive();
	}

	private int followSteps()
	{
		return 1 + (int) Math.ceil(size.getTiles());
	}

	private void move(int cycles)
	{
		Player player = client.getLocalPlayer();
		LocalPoint here = player == null ? null : player.getLocalLocation();
		double dx = target == null ? 0 : target.getX() - x;
		double dy = target == null ? 0 : target.getY() - y;
		double distance = Math.hypot(dx, dy);

		if (distance < 1)
		{
			if (walking)
			{
				walking = false;
				pose();
			}
			// Standing still, so look at the player.
			if (here != null)
			{
				turnTowards(here.getX() - x, here.getY() - y, cycles);
			}
			return;
		}

		double speed = Math.max(WALK_SPEED, Math.min(MAX_SPEED, distance / CATCH_UP_CYCLES));
		double step = Math.min(distance, speed * cycles);
		x += dx / distance * step;
		y += dy / distance * step;
		object.setLocation(new LocalPoint((int) Math.round(x), (int) Math.round(y), client.getTopLevelWorldView()), object.getLevel());
		turnTowards(dx, dy, cycles);
		if (!walking)
		{
			walking = true;
			pose();
		}
	}

	private void turnTowards(double dx, double dy, int cycles)
	{
		if (Math.abs(dx) < 1 && Math.abs(dy) < 1)
		{
			return;
		}
		// Orientation 0 faces south and 512 west, in 2048ths of a turn.
		int wanted = (int) Math.round(Math.atan2(-dx, -dy) * 1024 / Math.PI) & 2047;
		int difference = ((wanted - orientation + 3072) & 2047) - 1024;
		int turn = Math.max(-TURN_SPEED * cycles, Math.min(TURN_SPEED * cycles, difference));
		orientation = (orientation + turn) & 2047;
		object.setOrientation(orientation);
	}

	private void spawn()
	{
		Player player = client.getLocalPlayer();
		if (!enabled || boss == null || player == null || player.getWorldView() != client.getTopLevelWorldView())
		{
			return;
		}

		WorldView worldView = client.getTopLevelWorldView();
		LocalPoint here = player.getLocalLocation();
		LocalPoint tile = pickTile(worldView, here);
		ModelData data = BossModels.load(client, boss, variant, size.getTiles());
		if (tile == null || data == null)
		{
			return;
		}

		Model model = data.light();
		modelHeight = BossModels.height(data.getVerticesY());
		if (object == null)
		{
			object = client.createRuneLiteObject();
		}
		object.setModel(model);
		object.setLocation(tile, worldView.getPlane());
		x = tile.getX();
		y = tile.getY();
		orientation = (int) Math.round(Math.atan2(-(here.getX() - x), -(here.getY() - y)) * 1024 / Math.PI) & 2047;
		object.setOrientation(orientation);
		trail.clear();
		trail.addLast(here);
		target = null;
		walking = false;
		object.setActive(true);

		if (boss.getSpawnAnimation() != -1)
		{
			spawning = true;
			playOnce(client.loadAnimation(boss.getSpawnAnimation()), this::pose);
		}
		else
		{
			pose();
			puff(tile, worldView.getPlane());
		}
	}

	private void finishDeath()
	{
		if (!dying)
		{
			return;
		}
		dying = false;
		hideAtCycle = -1;
		if (object != null)
		{
			object.setActive(false);
		}
		spawnAtCycle = client.getGameCycle() + RESPAWN_DELAY_CYCLES;
	}

	// Loops the walk or idle animation, whichever fits.
	private void pose()
	{
		spawning = false;
		if (object == null || boss == null || dying)
		{
			return;
		}
		// A new controller loops by default.
		object.setAnimation(client.loadAnimation(walking ? boss.getWalkAnimation() : boss.getIdleAnimation()));
	}

	private void playOnce(Animation animation, Runnable after)
	{
		if (object == null)
		{
			return;
		}
		if (animation == null)
		{
			after.run();
			return;
		}
		object.setAnimationController(new AnimationController(client, animation).setOnFinished(c -> after.run()));
	}

	private void puff(LocalPoint tile, int plane)
	{
		ModelData data = client.loadModelData(SMOKE_PUFF_MODEL);
		Animation animation = client.loadAnimation(AnimationID.SMOKEPUFF);
		if (data == null || animation == null)
		{
			return;
		}

		int scale = (int) Math.round(MODEL_SCALE_UNIT * size.getTiles());
		if (puff == null)
		{
			puff = client.createRuneLiteObject();
		}
		RuneLiteObject smoke = puff;
		smoke.setModel(data.shallowCopy().cloneVertices().scale(scale, scale, scale).light());
		smoke.setLocation(tile, plane);
		smoke.setAnimationController(new AnimationController(client, animation).setOnFinished(c -> smoke.setActive(false)));
		smoke.setActive(true);
	}

	private static LocalPoint pickTile(WorldView worldView, LocalPoint player)
	{
		if (player == null)
		{
			return null;
		}
		CollisionData[] maps = worldView.getCollisionMaps();
		int plane = worldView.getPlane();
		int[][] flags = maps != null && maps[plane] != null ? maps[plane].getFlags() : null;
		for (int[] offset : SPAWN_OFFSETS)
		{
			int tileX = player.getSceneX() + offset[0];
			int tileY = player.getSceneY() + offset[1];
			if (tileX < 1 || tileY < 1 || tileX >= worldView.getSizeX() - 1 || tileY >= worldView.getSizeY() - 1)
			{
				continue;
			}
			if (flags != null && (flags[tileX][tileY] & BLOCKED) != 0)
			{
				continue;
			}
			return LocalPoint.fromScene(tileX, tileY, worldView);
		}
		return null;
	}

	private static int tiles(LocalPoint a, LocalPoint b)
	{
		if (a == null || b == null)
		{
			return Integer.MAX_VALUE;
		}
		return Math.max(Math.abs(a.getSceneX() - b.getSceneX()), Math.abs(a.getSceneY() - b.getSceneY()));
	}
}

package com.idlebosses;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum MiniBossSize
{
	SMALL("Small", 1.0),
	MEDIUM("Medium", 1.5),
	LARGE("Large", 2.2);

	private final String label;
	// How many tiles wide the mini boss is, whatever the real boss's size.
	private final double tiles;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.idlebosses;

import java.util.Arrays;
import java.util.function.IntUnaryOperator;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;

// Flattens a posed boss model into triangles seen from a fixed three-quarter angle, using the colours the game lit
// it with. The angle, which faces count as facing away, and the depth order were checked by rendering the bosses
// from the game cache.
final class ModelProjector
{
	private static final double YAW = 0.6;
	private static final double PITCH = 0.3;
	// A face's third colour is -1 when it's one flat colour, and -2 when it isn't drawn.
	private static final int FLAT = -1;
	private static final int HIDDEN = -2;
	private static final int OPAQUE_LIMIT = 254;
	// The game's default brightness.
	private static final double BRIGHTNESS = 0.7;
	private static final int[] PALETTE = palette();

	private ModelProjector()
	{
	}

	// textureColor gives a texture's own colour, which textured faces are drawn in.
	static BossFrame project(Model model, IntUnaryOperator textureColor)
	{
		return project(model.getVerticesCount(), model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(),
			model.getFaceCount(), model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
			model.getFaceColors1(), model.getFaceColors2(), model.getFaceColors3(), model.getFaceTransparencies(),
			model.getFaceTextures(), textureColor);
	}

	// Colours are the game's lit HSL values, one per corner. A textured face's colours are only its lighting.
	static BossFrame project(int vertices, float[] vx, float[] vy, float[] vz, int faces, int[] a, int[] b, int[] c,
		int[] colors1, int[] colors2, int[] colors3, byte[] transparency, short[] textures, IntUnaryOperator textureColor)
	{
		double cosYaw = Math.cos(YAW);
		double sinYaw = Math.sin(YAW);
		double cosPitch = Math.cos(PITCH);
		double sinPitch = Math.sin(PITCH);

		float[] sx = new float[vertices];
		float[] sy = new float[vertices];
		float[] depth = new float[vertices];
		for (int v = 0; v < vertices; v++)
		{
			double x = vx[v] * cosYaw - vz[v] * sinYaw;
			double z = vx[v] * sinYaw + vz[v] * cosYaw;
			sx[v] = (float) x;
			sy[v] = (float) (vy[v] * cosPitch - z * sinPitch);
			depth[v] = (float) (vy[v] * sinPitch + z * cosPitch);
		}

		// Sort by depth with the face number packed underneath, furthest last.
		long[] order = new long[faces];
		int shown = 0;
		for (int f = 0; f < faces; f++)
		{
			if (colors3[f] == HIDDEN || transparency != null && (transparency[f] & 0xFF) >= OPAQUE_LIMIT)
			{
				continue;
			}
			int i = a[f];
			int j = b[f];
			int k = c[f];
			float facing = (sx[i] - sx[j]) * (sy[k] - sy[j]) - (sy[i] - sy[j]) * (sx[k] - sx[j]);
			if (facing <= 0)
			{
				continue;
			}
			long key = Math.round((depth[i] + depth[j] + depth[k]) * 4) + (1L << 30);
			order[shown++] = key << 32 | f;
		}
		Arrays.sort(order, 0, shown);

		float[] x = new float[shown * 3];
		float[] y = new float[shown * 3];
		int[] rgb = new int[shown];
		float minX = Float.MAX_VALUE;
		float maxX = -Float.MAX_VALUE;
		float minY = Float.MAX_VALUE;
		float maxY = -Float.MAX_VALUE;
		for (int n = 0; n < shown; n++)
		{
			int f = (int) order[shown - 1 - n];
			int[] corners = {a[f], b[f], c[f]};
			for (int corner = 0; corner < 3; corner++)
			{
				int v = corners[corner];
				x[n * 3 + corner] = sx[v];
				y[n * 3 + corner] = sy[v];
				minX = Math.min(minX, sx[v]);
				maxX = Math.max(maxX, sx[v]);
				minY = Math.min(minY, sy[v]);
				maxY = Math.max(maxY, sy[v]);
			}
			int color = faceColor(colors1[f], colors2[f], colors3[f]);
			if (textures != null && textures[f] >= 0 && textureColor != null)
			{
				// The texture's colour, at this face's lighting, as the game draws it with textures off.
				color = hsl(textureColor.applyAsInt(textures[f])) & 0xFF80 | color & 0x7F;
			}
			rgb[n] = PALETTE[color];
		}
		return new BossFrame(x, y, rgb, shown, minX, maxX, minY, maxY);
	}

	// A smooth-shaded face has a lit colour at each corner; one flat colour is close enough at this size.
	private static int faceColor(int first, int second, int third)
	{
		if (third == FLAT)
		{
			return first & 0xFFFF;
		}
		int lightness = ((first & 0x7F) + (second & 0x7F) + (third & 0x7F)) / 3;
		return (first & 0xFF80 | lightness) & 0xFFFF;
	}

	// The texture colour should already be the game's HSL; an RGB one is converted.
	private static int hsl(int color)
	{
		return color > 0xFFFF ? JagexColor.rgbToHSL(color, BRIGHTNESS) & 0xFFFF : color;
	}

	// The game's colours are 6 bits of hue, 3 of saturation and 7 of lightness. This is how it turns them into RGB.
	private static int[] palette()
	{
		int[] palette = new int[1 << 16];
		for (int hsl = 0; hsl < palette.length; hsl++)
		{
			double hue = (hsl >> 10 & 0x3F) / 64.0 + 0.0078125;
			double saturation = (hsl >> 7 & 0x7) / 8.0 + 0.0625;
			double lightness = (hsl & 0x7F) / 128.0;
			double q = lightness < 0.5 ? lightness * (1 + saturation) : lightness + saturation - lightness * saturation;
			double p = 2 * lightness - q;
			int r = channel(p, q, hue + 1 / 3.0);
			int g = channel(p, q, hue);
			int bl = channel(p, q, hue - 1 / 3.0);
			palette[hsl] = r << 16 | g << 8 | bl;
		}
		return palette;
	}

	private static int channel(double p, double q, double t)
	{
		if (t < 0)
		{
			t += 1;
		}
		if (t > 1)
		{
			t -= 1;
		}
		double value;
		if (6 * t < 1)
		{
			value = p + (q - p) * 6 * t;
		}
		else if (2 * t < 1)
		{
			value = q;
		}
		else if (3 * t < 2)
		{
			value = p + (q - p) * (2 / 3.0 - t) * 6;
		}
		else
		{
			value = p;
		}
		return Math.min(255, (int) (Math.pow(value, BRIGHTNESS) * 256));
	}
}

package com.idlebosses;

import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

// What a player has done, saved as JSON per account: kill counts, loot, collection log items, loot value, and the
// coins, gear and cannon bought with it. Like the game's collection log, an item counts once however many bosses'
// logs it's on.
final class Progress
{
	String currentBoss;
	// Everything ever looted, at Grand Exchange prices. Spending coins doesn't lower it.
	long gpLooted;
	// Coins to spend on upgrades. Missing from saves made before upgrades; they start with what they'd looted.
	Long coins;
	Map<String, BossProgress> bosses = new HashMap<>();
	Set<Integer> logItems = new LinkedHashSet<>();
	// Where and when each log item first dropped. Missing for items from saves before it was kept.
	Map<Integer, LogDrop> logDrops = new HashMap<>();
	// Gear bought, by Gear name.
	Set<String> gear = new LinkedHashSet<>();
	// The Gear name of the weapon wielded, or null.
	String weapon;
	CannonState cannon = new CannonState();

	static final class CannonState
	{
		boolean owned;
		// In the bank.
		long cannonballs;
		long granite;
		// In the cannon. Granite ones fire first.
		int loaded;
		int loadedGranite;
	}

	static final class LogDrop
	{
		// The boss's id.
		String boss;
		// The boss's kill count on the kill that dropped it.
		int kills;
	}

	static final class BossProgress
	{
		int kills;
		// Each boss's own log, from before items were shared. Read from old saves and folded into logItems.
		Set<Integer> log;
		// Everything the boss has dropped, by item ID.
		Map<Integer, Long> loot = new HashMap<>();
	}

	private BossProgress get(Boss boss)
	{
		if (bosses == null)
		{
			bosses = new HashMap<>();
		}
		BossProgress progress = bosses.computeIfAbsent(boss.getId(), id -> new BossProgress());
		if (progress.loot == null)
		{
			progress.loot = new HashMap<>();
		}
		return progress;
	}

	// Moves an old save's per-boss logs into the shared one, and fills in anything an old save didn't have.
	Progress migrate()
	{
		if (logItems == null)
		{
			logItems = new LinkedHashSet<>();
		}
		if (logDrops == null)
		{
			logDrops = new HashMap<>();
		}
		if (coins == null)
		{
			coins = gpLooted;
		}
		if (gear == null)
		{
			gear = new LinkedHashSet<>();
		}
		if (cannon == null)
		{
			cannon = new CannonState();
		}
		if (bosses != null)
		{
			for (BossProgress progress : bosses.values())
			{
				if (progress.log != null)
				{
					logItems.addAll(progress.log);
					progress.log = null;
				}
			}
		}
		return this;
	}

	int kills(Boss boss)
	{
		return get(boss).kills;
	}

	void addKill(Boss boss)
	{
		get(boss).kills++;
	}

	boolean hasLogItem(int itemId)
	{
		return logItems.contains(itemId);
	}

	// True if the item is new to the collection log.
	boolean addLogItem(int itemId)
	{
		return logItems.add(itemId);
	}

	// Like addLogItem, remembering the boss that dropped it and its kill count.
	boolean addLogItem(int itemId, Boss boss)
	{
		if (!addLogItem(itemId))
		{
			return false;
		}
		LogDrop drop = new LogDrop();
		drop.boss = boss.getId();
		drop.kills = kills(boss);
		logDrops.put(itemId, drop);
		return true;
	}

	// Where and when the item first dropped, or null if that wasn't kept.
	LogDrop logDrop(int itemId)
	{
		return logDrops == null ? null : logDrops.get(itemId);
	}

	// How many of these log items are filled.
	int logCount(Collection<Integer> log)
	{
		int count = 0;
		for (int itemId : log)
		{
			if (logItems.contains(itemId))
			{
				count++;
			}
		}
		return count;
	}

	int totalSlots()
	{
		return logItems.size();
	}

	int totalKills()
	{
		int total = 0;
		for (Boss boss : Boss.values())
		{
			total += kills(boss);
		}
		return total;
	}

	// Enough log slots across every boss, and enough kills of the boss before it. A boss you've fought stays unlocked.
	boolean isUnlocked(Boss boss)
	{
		if (kills(boss) > 0)
		{
			return true;
		}
		Boss previous = boss.previous();
		return totalSlots() >= boss.getUnlockSlots() && (previous == null || kills(previous) >= boss.unlockKills());
	}

	void addLoot(Boss boss, int itemId, long quantity)
	{
		get(boss).loot.merge(itemId, quantity, Long::sum);
	}

	Map<Integer, Long> loot(Boss boss)
	{
		return get(boss).loot;
	}

	long coins()
	{
		return coins == null ? gpLooted : coins;
	}

	// Loot adds to both the lifetime total and the coins to spend.
	void addLootValue(long value)
	{
		gpLooted += value;
		coins = coins() + value;
	}

	boolean owns(Gear item)
	{
		return gear != null && gear.contains(item.name());
	}

	// The highest tier owned in a ladder, which is the one worn.
	Gear best(Gear.Slot slot)
	{
		Gear best = null;
		for (Gear item : Gear.inSlot(slot))
		{
			if (owns(item))
			{
				best = item;
			}
		}
		return best;
	}

	Gear wielded()
	{
		Gear item = weapon == null ? null : Gear.byName(weapon);
		return item != null && owns(item) ? item : null;
	}
}

package com.idlebosses;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

// Spending coins: gear, the cannon and its cannonballs, and loading and firing the cannon. Works on Progress only,
// so it can be tested without a client.
final class Shop
{
	// It's worth about as much damage as the amulet of torture, but costs cannonballs and reloading.
	static final long CANNON_PRICE = 25_000_000;
	// An hour of fire uses about 750, so regular balls cost about 1.1M an hour and granite about 3M.
	static final long CANNONBALL_PRICE = 1_500;
	static final long GRANITE_PRICE = 4_000;
	static final int BALLS_PER_PURCHASE = 100;
	static final int CANNON_CAPACITY = 30;
	// Game ticks between shots, 4.8 seconds.
	static final int CANNON_FIRE_TICKS = 8;
	// About a fifth of what you'd deal between shots at a typical pace, before the boss's toughness.
	static final int CANNON_MAX_HIT = 8;
	static final double GRANITE_BONUS = 0.2;

	private Shop()
	{
	}

	// Collection log items it still needs.
	static List<Integer> missing(Progress progress, Gear item)
	{
		List<Integer> missing = new ArrayList<>();
		for (int itemId : item.getRequires())
		{
			if (!progress.hasLogItem(itemId))
			{
				missing.add(itemId);
			}
		}
		return missing;
	}

	static boolean canBuy(Progress progress, Gear item)
	{
		Gear previous = item.previousTier();
		return !progress.owns(item)
			&& (previous == null || progress.owns(previous))
			&& missing(progress, item).isEmpty()
			&& progress.coins() >= item.getPrice();
	}

	// Buys it if you can. A new weapon is wielded straight away.
	static boolean buy(Progress progress, Gear item)
	{
		if (!canBuy(progress, item))
		{
			return false;
		}
		progress.coins = progress.coins() - item.getPrice();
		progress.gear.add(item.name());
		if (item.getSlot() == Gear.Slot.WEAPON)
		{
			progress.weapon = item.name();
		}
		return true;
	}

	static boolean wield(Progress progress, Gear item)
	{
		if (item.getSlot() != Gear.Slot.WEAPON || !progress.owns(item))
		{
			return false;
		}
		progress.weapon = item.name();
		return true;
	}

	static boolean buyCannon(Progress progress)
	{
		if (progress.cannon.owned || progress.coins() < CANNON_PRICE)
		{
			return false;
		}
		progress.coins = progress.coins() - CANNON_PRICE;
		progress.cannon.owned = true;
		return true;
	}

	static long ballPrice(boolean granite)
	{
		return (granite ? GRANITE_PRICE : CANNONBALL_PRICE) * BALLS_PER_PURCHASE;
	}

	static boolean buyCannonballs(Progress progress, boolean granite)
	{
		long price = ballPrice(granite);
		if (!progress.cannon.owned || progress.coins() < price)
		{
			return false;
		}
		progress.coins = progress.coins() - price;
		if (granite)
		{
			progress.cannon.granite += BALLS_PER_PURCHASE;
		}
		else
		{
			progress.cannon.cannonballs += BALLS_PER_PURCHASE;
		}
		return true;
	}

	// Fills the cannon from the bank, granite first. Returns how many went in.
	static int reload(Progress progress)
	{
		Progress.CannonState cannon = progress.cannon;
		if (!cannon.owned)
		{
			return 0;
		}
		int room = CANNON_CAPACITY - cannon.loaded;
		int granite = (int) Math.min(room, cannon.granite);
		int regular = (int) Math.min(room - granite, cannon.cannonballs);
		cannon.granite -= granite;
		cannon.cannonballs -= regular;
		cannon.loaded += granite + regular;
		cannon.loadedGranite += granite;
		return granite + regular;
	}

	// One shot at the boss, or null when the cannon's empty. The Kodai wand sometimes saves the ball.
	static Hit fire(Progress progress, Boss boss, double saveChance, Random random)
	{
		Progress.CannonState cannon = progress.cannon;
		if (!cannon.owned || cannon.loaded <= 0 || boss == null)
		{
			return null;
		}
		boolean granite = cannon.loadedGranite > 0;
		if (random.nextDouble() >= saveChance)
		{
			cannon.loaded--;
			if (granite)
			{
				cannon.loadedGranite--;
			}
		}
		long maxHit = Math.round(CANNON_MAX_HIT * boss.damageScale() * (granite ? 1 + GRANITE_BONUS : 1));
		long damage = random.nextInt((int) Math.min(Integer.MAX_VALUE - 1, maxHit) + 1);
		return new Hit(damage, damage > 0 ? Hit.Type.CANNON : Hit.Type.MISS);
	}
}

package com.idlebosses;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

// Typical XP an hour for each skill, so an hour of any skill hits about as hard.
// Hitpoints and Slayer only come alongside combat XP, so they don't hit at all.
final class SkillRates
{
	// At a skill's typical rate you deal this much damage an hour: 4 a second.
	static final double DAMAGE_PER_HOUR = 14_400;

	private static final Map<Skill, Integer> XP_PER_HOUR = new EnumMap<>(Skill.class);

	static
	{
		XP_PER_HOUR.put(Skill.ATTACK, 70_000);
		XP_PER_HOUR.put(Skill.STRENGTH, 70_000);
		XP_PER_HOUR.put(Skill.DEFENCE, 70_000);
		XP_PER_HOUR.put(Skill.RANGED, 80_000);
		XP_PER_HOUR.put(Skill.MAGIC, 100_000);
		XP_PER_HOUR.put(Skill.PRAYER, 300_000);
		XP_PER_HOUR.put(Skill.RUNECRAFT, 50_000);
		XP_PER_HOUR.put(Skill.CONSTRUCTION, 300_000);
		XP_PER_HOUR.put(Skill.AGILITY, 50_000);
		XP_PER_HOUR.put(Skill.HERBLORE, 200_000);
		XP_PER_HOUR.put(Skill.THIEVING, 150_000);
		XP_PER_HOUR.put(Skill.CRAFTING, 150_000);
		XP_PER_HOUR.put(Skill.FLETCHING, 200_000);
		XP_PER_HOUR.put(Skill.HUNTER, 80_000);
		XP_PER_HOUR.put(Skill.MINING, 50_000);
		XP_PER_HOUR.put(Skill.SMITHING, 150_000);
		XP_PER_HOUR.put(Skill.FISHING, 50_000);
		XP_PER_HOUR.put(Skill.COOKING, 250_000);
		XP_PER_HOUR.put(Skill.FIREMAKING, 200_000);
		XP_PER_HOUR.put(Skill.WOODCUTTING, 50_000);
		XP_PER_HOUR.put(Skill.FARMING, 150_000);
		XP_PER_HOUR.put(Skill.SAILING, 60_000);
	}

	private SkillRates()
	{
	}

	// 0 for a skill that doesn't hit.
	static int xpPerHour(Skill skill)
	{
		return XP_PER_HOUR.getOrDefault(skill, 0);
	}
}

package com.idlebosses;

import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Singleton;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;

// The game's hitsplat for each kind of hit, shared by the HUD, the sidebar and the walking boss.
// Loaded once in the background; until a splat has loaded, the normal red one stands in.
@Singleton
class SplatSprites
{
	private final Map<Hit.Type, BufferedImage> sprites = new ConcurrentHashMap<>();

	void load(SpriteManager spriteManager)
	{
		for (Hit.Type type : Hit.Type.values())
		{
			spriteManager.getSpriteAsync(spriteId(type), 0, sprite ->
			{
				if (sprite != null)
				{
					sprites.put(type, sprite);
				}
			});
		}
	}

	BufferedImage get(Hit.Type type)
	{
		BufferedImage sprite = sprites.get(type);
		return sprite != null ? sprite : sprites.get(Hit.Type.NORMAL);
	}

	private static int spriteId(Hit.Type type)
	{
		switch (type)
		{
			// The max hit splat.
			case CRITICAL:
				return SpriteID.Hitmark._24;
			case POISON:
				return SpriteID.Hitmark._2;
			case CANNON:
				return SpriteID.Hitmark._12;
			case MISS:
				return SpriteID.Hitmark._0;
			// The venom splat, for the toxic blowpipe.
			case DART:
				return SpriteID.Hitmark._11;
			default:
				return SpriteID.Hitmark._1;
		}
	}
}

package com.idlebosses;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Skill;
import org.junit.Test;

public class BossFightTest
{
	@Test
	public void anHourOfAnySkillHitsAsHard()
	{
		// 35 Mining XP at 50k an hour, and 210 Fletching XP at 200k an hour, are both about 10 damage.
		assertEquals(10, BossFight.damage(Skill.MINING, 35, Skill.FARMING, 0));
		assertEquals(15, BossFight.damage(Skill.FLETCHING, 210, Skill.FARMING, 0));
		assertEquals(4 * 3600, Math.round(50_000 * SkillRates.DAMAGE_PER_HOUR / SkillRates.xpPerHour(Skill.MINING)));
	}

	@Test
	public void weaknessDoublesAndStreakAddsUp()
	{
		assertEquals(20, BossFight.damage(Skill.MINING, 35, Skill.MINING, 0));
		// +10% for a 10 kill streak, and the bonus stops at 25%.
		assertEquals(11, BossFight.damage(Skill.MINING, 35, Skill.FARMING, 10));
		assertEquals(BossFight.damage(Skill.MINING, 70, Skill.FARMING, 25), BossFight.damage(Skill.MINING, 70, Skill.FARMING, 90));
	}

	@Test
	public void bigDropsHitInFullAndTinyOnesStillHit()
	{
		// A 10k Woodcutting lamp is 2,880 damage, with no limit.
		assertEquals(2_880, BossFight.damage(Skill.WOODCUTTING, 10_000, Skill.FARMING, 0));
		assertEquals(1, BossFight.damage(Skill.COOKING, 1, Skill.FARMING, 0));
	}

	@Test
	public void hitpointsAndSlayerDontHit()
	{
		assertEquals(0, BossFight.damage(Skill.HITPOINTS, 400, Skill.FARMING, 0));
		assertEquals(0, BossFight.damage(Skill.SLAYER, 400, Skill.FARMING, 0));
	}

	@Test
	public void killsAddToTheStreak()
	{
		BossFight fight = new BossFight();
		fight.start(Boss.OBOR, false);
		assertEquals(120, fight.getHp());

		// 40 XP at 50k an hour is 11.5 damage, doubled for Obor's weakness to Woodcutting: 23 a hit.
		int hits = 0;
		do
		{
			assertEquals(23, fight.hit(Skill.WOODCUTTING, 40, 1_000));
			hits++;
		}
		while (!fight.land());
		assertEquals(6, hits);
		assertEquals(0, fight.getHp());
		assertEquals(1, fight.getStreak());
		// 6 hits of 23 is 138: 18 carries on to the next boss.
		assertEquals(18, fight.getPending());
		fight.start(Boss.OBOR, false);
		assertFalse(fight.land());
		assertEquals(102, fight.getHp());
		assertEquals(0, fight.getPending());
	}

	@Test
	public void oneBigDropKillsSeveralBosses()
	{
		BossFight fight = new BossFight();
		fight.start(Boss.OBOR, false);
		// 5,760 damage against 120 HP bosses: 48 kills exactly.
		fight.hit(Skill.WOODCUTTING, 10_000, 0);
		int kills = 0;
		while (fight.land())
		{
			kills++;
			fight.start(Boss.OBOR, false);
		}
		assertEquals(48, kills);
		assertEquals(120, fight.getHp());
		assertEquals(0, fight.getPending());
	}

	@Test
	public void superiorsHaveDoubleHealth()
	{
		BossFight fight = new BossFight();
		fight.start(Boss.GIANT_MOLE, true);
		assertTrue(fight.isSuperior());
		assertEquals(400, fight.getMaxHp());
	}

	@Test
	public void streakEndsAfterAMinuteWithoutXp()
	{
		BossFight fight = new BossFight();
		fight.start(Boss.OBOR, false);
		fight.hit(Skill.WOODCUTTING, 1_000, 0);
		assertTrue(fight.land());
		fight.start(Boss.OBOR, false);
		fight.clearPending();
		assertEquals(0, fight.expireStreak(BossFight.STREAK_TIMEOUT_MILLIS));
		assertEquals(1, fight.expireStreak(BossFight.STREAK_TIMEOUT_MILLIS + 1));
		assertEquals(0, fight.getStreak());
	}

	@Test
	public void heightIsTheTallestPoint()
	{
		assertEquals(150, BossModels.height(new float[]{0, -40, -150, 2}));
		assertEquals(150, BossModels.height(new float[]{0, 40, 150, -2}));
	}

	@Test
	public void tintKeepsLightness()
	{
		short color = (short) (21 << 10 | 3 << 7 | 70);
		assertEquals(70, BossModels.tint(color, MiniBoss.Variant.SUPERIOR) & 0x7F);
		assertEquals(82, BossModels.tint(color, MiniBoss.Variant.GOLD) & 0x7F);
		assertFalse(BossModels.tint(color, MiniBoss.Variant.GOLD) == color);
	}
}

package com.idlebosses;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class DropDataTest
{
	static DropData load() throws Exception
	{
		try (Reader reader = new InputStreamReader(IdleBossesPlugin.class.getResourceAsStream("drops.json"), StandardCharsets.UTF_8))
		{
			return new Gson().fromJson(reader, DropData.class).normalize();
		}
	}

	@Test
	public void everyBossHasDropsAndALog() throws Exception
	{
		DropData data = load();
		for (Boss boss : Boss.values())
		{
			DropData.BossDrops drops = data.boss(boss);
			assertNotNull(boss + " has no drops", drops);
			assertFalse(boss + " has no collection log", drops.log.isEmpty());
			assertTrue(boss + " has no main table", drops.mainOutOf > 0 || drops.main.isEmpty());
		}
	}

	@Test
	public void weightsFitTheirTables() throws Exception
	{
		DropData data = load();
		for (DropData.BossDrops drops : data.bosses)
		{
			int total = sum(drops.main) + sum(drops.tables);
			assertTrue(drops.id + " main weights " + total + " are over " + drops.mainOutOf, total <= drops.mainOutOf);
			for (DropData.Drop table : drops.tables)
			{
				assertNotNull(drops.id + " links to a missing table " + table.table, data.table(table.table));
			}
			for (DropData.Drop drop : drops.tertiary)
			{
				assertTrue(drops.id + " " + drop.name, drop.numerator > 0 && drop.denominator >= drop.numerator);
			}
			if (drops.preRoll != null)
			{
				assertTrue(drops.id + " unique roll", drops.preRoll.numerator > 0 && drops.preRoll.denominator >= drops.preRoll.numerator);
				assertNotNull(drops.id + " unique roll opens a missing table", data.table(drops.preRoll.table));
			}
		}
		for (String name : data.sharedTables.keySet())
		{
			DropData.SharedTable table = data.table(name);
			assertTrue(name + " weights are over " + table.outOf, sum(table.entries) <= table.outOf);
		}
	}

	@Test
	public void everyLogItemCanDrop() throws Exception
	{
		DropData data = load();
		for (DropData.BossDrops drops : data.bosses)
		{
			Set<Integer> reachable = new HashSet<>();
			collect(data, drops.always, reachable, 0);
			collect(data, drops.main, reachable, 0);
			collect(data, drops.tables, reachable, 0);
			collect(data, drops.tertiary, reachable, 0);
			if (drops.preRoll != null)
			{
				collect(data, List.of(drops.preRoll), reachable, 0);
			}
			for (int itemId : drops.log)
			{
				assertTrue(drops.id + " log item " + itemId + " never drops", reachable.contains(itemId));
			}
		}
	}

	private static void collect(DropData data, List<DropData.Drop> drops, Set<Integer> into, int depth)
	{
		for (DropData.Drop drop : drops)
		{
			if (drop.table != null)
			{
				DropData.SharedTable table = data.table(drop.table);
				if (table != null && depth < 3)
				{
					collect(data, table.entries, into, depth + 1);
				}
			}
			else
			{
				assertTrue(drop.name + " has no item id", drop.itemId > 0);
				into.add(drop.itemId);
			}
		}
	}

	private static int sum(List<DropData.Drop> drops)
	{
		return drops.stream().mapToInt(d -> d.weight).sum();
	}
}

package com.idlebosses;

import static org.junit.Assert.assertEquals;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class DropRatesTest
{
	@Test
	public void addsUpEveryRoute()
	{
		DropData data = LootRollerTest.data();
		DropData.BossDrops boss = data.bosses.get(0);
		Map<Integer, Double> rates = DropRates.perKill(data, boss);
		assertEquals(1, rates.get(532), 1e-9);
		assertEquals(0.5, rates.get(1), 1e-9);
		assertEquals(0.2 / 4, rates.get(1621), 1e-9);
		assertEquals(1.0 / 50, rates.get(3), 1e-9);

		// Two rolls: the chance of at least one.
		boss.rolls = 2;
		assertEquals(0.75, DropRates.perKill(data, boss).get(1), 1e-9);
	}

	@Test
	public void matchesTheWikiForRealBosses() throws Exception
	{
		DropData data = DropDataTest.load();
		Map<Integer, Double> mole = DropRates.perKill(data, data.boss(Boss.GIANT_MOLE));
		assertEquals("Always", DropRates.format(mole.get(ItemID.MOLE_SKIN)));
		assertEquals("1/3,000", DropRates.format(mole.get(ItemID.MOLEPET)));

		Map<Integer, Double> vorkath = DropRates.perKill(data, data.boss(Boss.VORKATH));
		assertEquals("1/50", DropRates.format(vorkath.get(ItemID.VORKATH_HEAD)));

		Map<Integer, Double> obor = DropRates.perKill(data, data.boss(Boss.OBOR));
		assertEquals("1/118", DropRates.format(obor.get(ItemID.HILLGIANT_BOSS_CLUB)));
	}

	@Test
	public void formatsLikeTheWiki()
	{
		assertEquals("Always", DropRates.format(1));
		assertEquals("1/8.6", DropRates.format(1 / 8.6));
		assertEquals("1/128", DropRates.format(1.0 / 128));
		assertEquals("1/5,000", DropRates.format(1.0 / 5000));
	}
}

