package com.idlebosses;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.Random;
import org.junit.Test;

public class LoadoutTest
{
	private static BossFight fight(Boss boss)
	{
		BossFight fight = new BossFight();
		fight.start(boss, false);
		return fight;
	}

	private static long total(List<Hit> hits)
	{
		return hits.stream().mapToLong(Hit::getDamage).sum();
	}

	@Test
	public void theAmuletAddsFlatDamage()
	{
		Loadout loadout = new Loadout(Gear.AMULET_OF_FURY, null, null);
		List<Hit> hits = loadout.attack(100, fight(Boss.OBOR), new Random(1)).getHits();
		assertEquals(1, hits.size());
		assertEquals(107, hits.get(0).getDamage());
		assertEquals(Hit.Type.NORMAL, hits.get(0).getType());
	}

	@Test
	public void tumekensShadowDoublesTheAmulet()
	{
		Loadout loadout = new Loadout(Gear.AMULET_OF_FURY, null, Gear.TUMEKENS_SHADOW);
		assertEquals(114, total(loadout.attack(100, fight(Boss.OBOR), new Random(1)).getHits()));
	}

	@Test
	public void glovesGiveCriticalHits()
	{
		assertEquals(0.06, critRate(new Loadout(null, Gear.FEROCIOUS_GLOVES, null), 200), 0.005);
		// Osmumten's fang rolls twice.
		assertEquals(1 - 0.94 * 0.94, critRate(new Loadout(null, Gear.FEROCIOUS_GLOVES, Gear.OSMUMTENS_FANG), 200), 0.005);
		// The Armadyl crossbow's critical hits deal 3x.
		assertEquals(0.06, critRate(new Loadout(null, Gear.FEROCIOUS_GLOVES, Gear.ARMADYL_CROSSBOW), 300), 0.005);
	}

	private static double critRate(Loadout loadout, long critDamage)
	{
		Random random = new Random(3);
		int drops = 100_000;
		int crits = 0;
		for (int i = 0; i < drops; i++)
		{
			Hit hit = loadout.attack(100, fight(Boss.OBOR), random).getHits().get(0);
			if (hit.getType() == Hit.Type.CRITICAL)
			{
				assertEquals(critDamage, hit.getDamage());
				crits++;
			}
		}
		return (double) crits / drops;
	}

	@Test
	public void clawsAndScytheSplitADropIntoSeveralHits()
	{
		Random random = new Random(5);
		boolean sawClaws = false;
		for (int i = 0; i < 1_000 && !sawClaws; i++)
		{
			List<Hit> hits = new Loadout(null, null, Gear.DRAGON_CLAWS).attack(100, fight(Boss.OBOR), random).getHits();
			if (hits.size() > 1)
			{
				assertEquals(4, hits.size());
				assertEquals(200, total(hits));
				sawClaws = true;
			}
		}
		assertTrue(sawClaws);

		boolean sawScythe = false;
		for (int i = 0; i < 1_000 && !sawScythe; i++)
		{
			List<Hit> hits = new Loadout(null, null, Gear.SCYTHE_OF_VITUR).attack(100, fight(Boss.OBOR), random).getHits();
			if (hits.size() > 1)
			{
				assertEquals(3, hits.size());
				assertEquals(175, total(hits));
				sawScythe = true;
			}
		}
		assertTrue(sawScythe);
	}

	@Test
	public void slayerWeaponsOnlyWorkOnTheirBosses()
	{
		Loadout dragonHunter = new Loadout(null, null, Gear.DRAGON_HUNTER_CROSSBOW);
		assertEquals(120, total(dragonHunter.attack(100, fight(Boss.VORKATH), new Random(1)).getHits()));
		assertEquals(100, total(dragonHunter.attack(100, fight(Boss.OBOR), new Random(1)).getHits()));

		Loadout arclight = new Loadout(null, null, Gear.ARCLIGHT);
		assertEquals(120, total(arclight.attack(100, fight(Boss.KRIL_TSUTSAROTH), new Random(1)).getHits()));
		assertEquals(100, total(arclight.attack(100, fight(Boss.VORKATH), new Random(1)).getHits()));
	}

	@Test
	public void theTwistedBowScalesWithToughness()
	{
		Loadout bow = new Loadout(null, null, Gear.TWISTED_BOW);
		assertEquals(101, total(bow.attack(100, fight(Boss.OBOR), new Random(1)).getHits()));
		assertEquals(108, total(bow.attack(100, fight(Boss.NIGHTMARE), new Random(1)).getHits()));
		assertEquals(112, total(bow.attack(100, fight(Boss.TZKAL_ZUK), new Random(1)).getHits()));
	}

	@Test
	public void soulreaperStacksUntilTheBossDies()
	{
		Loadout axe = new Loadout(null, null, Gear.SOULREAPER_AXE);
		BossFight fight = fight(Boss.OBOR);
		long last = 0;
		for (int i = 0; i < 15; i++)
		{
			last = total(axe.attack(100, fight, new Random(1)).getHits());
		}
		assertEquals(110, last);
		fight.start(Boss.OBOR, false);
		assertEquals(100, total(axe.attack(100, fight, new Random(1)).getHits()));
	}

	@Test
	public void theBlowpipeFiresADartAndTheTentaclePoisons()
	{
		List<Hit> hits = new Loadout(null, null, Gear.TOXIC_BLOWPIPE).attack(100, fight(Boss.OBOR), new Random(1)).getHits();
		assertEquals(2, hits.size());
		assertEquals(Hit.Type.DART, hits.get(1).getType());
		assertEquals(1, hits.get(1).getDamage());

		BossFight fight = fight(Boss.OBOR);
		Loadout tentacle = new Loadout(null, null, Gear.ABYSSAL_TENTACLE);
		Random random = new Random(2);
		for (int i = 0; i < 100 && !fight.isPoisoned(); i++)
		{
			tentacle.attack(100, fight, random).getHits();
		}
		assertTrue(fight.isPoisoned());
		fight.start(Boss.OBOR, false);
		assertFalse(fight.isPoisoned());
	}

	@Test
	public void specialsSayWhatTheyDidAndStaggerTheirHits()
	{
		Random random = new Random(5);
		Loadout.Attack claws = null;
		for (int i = 0; i < 1_000 && claws == null; i++)
		{
			Loadout.Attack attack = new Loadout(null, null, Gear.DRAGON_CLAWS).attack(100, fight(Boss.OBOR), random);
			if (attack.getSpecial() != null)
			{
				claws = attack;
			}
		}
		assertEquals("x4", claws.getSpecial());
		assertEquals(4, claws.getStaggered());

		Loadout.Attack plain = new Loadout(null, null, Gear.DRAGON_SCIMITAR).attack(100, fight(Boss.OBOR), new Random(1));
		assertNull(plain.getSpecial());
		assertEquals(1, plain.getStaggered());

		assertEquals("+50%", firstSpecial(new Loadout(null, null, Gear.SANGUINESTI_STAFF)));
		assertEquals("x3", firstSpecial(new Loadout(null, Gear.FEROCIOUS_GLOVES, Gear.ARMADYL_CROSSBOW)));
		assertEquals("Second roll", firstSpecial(new Loadout(null, Gear.FEROCIOUS_GLOVES, Gear.OSMUMTENS_FANG)));
		assertEquals("Poisoned", firstSpecial(new Loadout(null, null, Gear.ABYSSAL_TENTACLE)));
	}

	private static String firstSpecial(Loadout loadout)
	{
		Random random = new Random(7);
		for (int i = 0; i < 1_000; i++)
		{
			String special = loadout.attack(100, fight(Boss.OBOR), random).getSpecial();
			if (special != null)
			{
				return special;
			}
		}
		return null;
	}

	@Test
	public void theVoidwakerFinishesLowBosses()
	{
		BossFight fight = fight(Boss.OBOR);
		double executeBelow = new Loadout(null, null, Gear.VOIDWAKER).executeBelow();
		// Obor has 120 hitpoints, so 9 left is under 8%.
		fight.addDamage(111);
		assertTrue(fight.land(executeBelow));
		assertEquals(9, fight.takeExecuted());
		assertEquals(0, fight.takeExecuted());

		fight.start(Boss.OBOR, false);
		fight.addDamage(100);
		assertFalse(fight.land(executeBelow));
		assertEquals(20, fight.getHp());
	}
}

package com.idlebosses;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

public class LootRollerTest
{
	private static DropData.Drop item(int id, String name, int weight)
	{
		DropData.Drop drop = new DropData.Drop();
		drop.itemId = id;
		drop.name = name;
		drop.weight = weight;
		return drop;
	}

	private static DropData.Drop tertiary(int id, String name, int numerator, int denominator)
	{
		DropData.Drop drop = item(id, name, 0);
		drop.numerator = numerator;
		drop.denominator = denominator;
		return drop;
	}

	private static DropData.Drop table(String name, int weight)
	{
		DropData.Drop drop = new DropData.Drop();
		drop.table = name;
		drop.weight = weight;
		return drop;
	}

	static DropData data()
	{
		DropData data = new DropData();
		DropData.SharedTable gems = new DropData.SharedTable();
		gems.outOf = 4;
		gems.entries = List.of(item(1623, "Uncut sapphire", 3), item(1621, "Uncut emerald", 1));
		data.sharedTables = Map.of("gem_drop_table", gems);

		DropData.BossDrops boss = new DropData.BossDrops();
		boss.id = "test";
		boss.always = List.of(item(532, "Big bones", 0));
		boss.main = List.of(item(1, "Common", 50), item(2, "Uncommon", 10));
		boss.tables = List.of(table("gem_drop_table", 20));
		// 20 of 100 gives nothing.
		boss.mainOutOf = 100;
		boss.tertiary = List.of(tertiary(3, "Pet", 1, 50));
		data.bosses = List.of(boss);
		return data.normalize();
	}

	@Test
	public void ratesMatchTheTable()
	{
		DropData data = data();
		LootRoller roller = new LootRoller(data, new Random(7));
		DropData.BossDrops boss = data.bosses.get(0);

		int kills = 100_000;
		Map<Integer, Integer> seen = new HashMap<>();
		for (int i = 0; i < kills; i++)
		{
			for (Loot loot : roller.roll(boss, false))
			{
				seen.merge(loot.getItemId(), 1, Integer::sum);
			}
		}

		assertEquals(kills, (int) seen.get(532));
		assertNear(0.50, seen.get(1), kills);
		assertNear(0.10, seen.get(2), kills);
		assertNear(0.20 * 3 / 4, seen.get(1623), kills);
		assertNear(0.20 / 4, seen.get(1621), kills);
		assertNear(1.0 / 50, seen.get(3), kills);
	}

	@Test
	public void chanceCarriesThroughSharedTables()
	{
		DropData data = data();
		LootRoller roller = new LootRoller(data, new Random(1));
		for (int i = 0; i < 2_000; i++)
		{
			for (Loot loot : roller.roll(data.bosses.get(0), false))
			{
				if (loot.getItemId() == 1621)
				{
					assertEquals(0.05, loot.getChance(), 1e-9);
					return;
				}
			}
		}
		throw new AssertionError("Never rolled the emerald");
	}

	@Test
	public void superiorsRollTheMainTableAgain()
	{
		DropData data = data();
		DropData.BossDrops boss = data.bosses.get(0);
		boss.main = List.of(item(1, "Common", 100));
		boss.tables = List.of();
		LootRoller roller = new LootRoller(data, new Random(3));
		assertEquals(1, quantity(roller.roll(boss, false), 1));
		assertEquals(2, quantity(roller.roll(boss, true), 1));
	}

	@Test
	public void tertiaryRollsCanOpenATable()
	{
		DropData data = data();
		DropData.BossDrops boss = data.bosses.get(0);
		DropData.Drop unsired = new DropData.Drop();
		unsired.table = "gem_drop_table";
		unsired.numerator = 1;
		unsired.denominator = 10;
		boss.tertiary = List.of(unsired);
		boss.main = List.of();
		boss.tables = List.of();

		LootRoller roller = new LootRoller(data, new Random(11));
		int kills = 100_000;
		int emeralds = 0;
		for (int i = 0; i < kills; i++)
		{
			emeralds += quantity(roller.roll(boss, false), 1621);
		}
		// 1/10 to open the table, then 1/4 for the emerald.
		assertNear(1.0 / 40, emeralds, kills);
		assertEquals(1.0 / 40, DropRates.perKill(data, boss).get(1621), 1e-9);
	}

	@Test
	public void aRaidUniqueReplacesTheCommonRolls()
	{
		DropData data = data();
		DropData.BossDrops boss = data.bosses.get(0);
		boss.main = List.of(item(1, "Common", 100));
		boss.tables = List.of();
		boss.rolls = 3;
		DropData.Drop unique = new DropData.Drop();
		unique.table = "gem_drop_table";
		unique.numerator = 1;
		unique.denominator = 5;
		boss.preRoll = unique;

		LootRoller roller = new LootRoller(data, new Random(5));
		int kills = 100_000;
		int uniques = 0;
		for (int i = 0; i < kills; i++)
		{
			List<Loot> loot = roller.roll(boss, false);
			int gems = quantity(loot, 1623) + quantity(loot, 1621);
			uniques += gems;
			assertEquals(gems > 0 ? 0 : 3, quantity(loot, 1));
		}
		assertNear(0.2, uniques, kills);

		Map<Integer, Double> rates = DropRates.perKill(data, boss);
		assertEquals(0.8, rates.get(1), 1e-9);
		assertEquals(0.2 / 4, rates.get(1621), 1e-9);
		assertEquals(1.0 / 50, rates.get(3), 1e-9);
	}

	@Test
	public void petsAreRare()
	{
		assertTrue(new Loot(3, "Pet", 1, 1.0 / 3000).isRare());
		assertTrue(!new Loot(4, "Club", 1, 1.0 / 50).isRare());
	}

	private static int quantity(List<Loot> loot, int itemId)
	{
		return loot.stream().filter(l -> l.getItemId() == itemId).mapToInt(Loot::getQuantity).sum();
	}

	private static void assertNear(double expected, int count, int kills)
	{
		assertEquals(expected, (double) count / kills, 0.006);
	}
}

package com.idlebosses;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Test;

public class ProgressTest
{
	@Test
	public void savesAndLoads()
	{
		Progress progress = new Progress();
		progress.currentBoss = Boss.GIANT_MOLE.getId();
		progress.gpLooted = 1_234_567;
		progress.addKill(Boss.GIANT_MOLE);
		progress.addKill(Boss.GIANT_MOLE);
		progress.addLogItem(7416);

		Gson gson = new Gson();
		Progress loaded = gson.fromJson(gson.toJson(progress), Progress.class);
		assertEquals("giant_mole", loaded.currentBoss);
		assertEquals(1_234_567, loaded.gpLooted);
		assertEquals(2, loaded.kills(Boss.GIANT_MOLE));
		assertTrue(loaded.hasLogItem(7416));
		assertFalse(loaded.addLogItem(7416));
	}

	@Test
	public void lootAddsUpAndSurvivesSaving()
	{
		Progress progress = new Progress();
		progress.addLoot(Boss.OBOR, 532, 1);
		progress.addLoot(Boss.OBOR, 532, 2);
		progress.addLoot(Boss.OBOR, 995, 3_000);

		Progress loaded = new Gson().fromJson(new Gson().toJson(progress), Progress.class);
		assertEquals(3L, (long) loaded.loot(Boss.OBOR).get(532));
		assertEquals(3_000L, (long) loaded.loot(Boss.OBOR).get(995));
		assertTrue(loaded.loot(Boss.VORKATH).isEmpty());
	}

	@Test
	public void oldPerBossLogsJoinTheSharedLog()
	{
		String old = "{\"bosses\":{\"obor\":{\"kills\":3,\"log\":[20756]},\"king_black_dragon\":{\"log\":[11920]}}}";
		Progress loaded = new Gson().fromJson(old, Progress.class).migrate();
		assertEquals(2, loaded.totalSlots());
		assertTrue(loaded.hasLogItem(11920));
		// A dragon pickaxe from one boss fills that slot on every boss's log, like the game.
		assertEquals(1, loaded.logCount(java.util.List.of(11920, 7980)));
		assertTrue(new Gson().toJson(loaded).indexOf("\"log\"") < 0);
	}

	@Test
	public void bossesNeedLogSlotsAndKillsOfTheOneBefore()
	{
		Boss first = null;
		for (Boss boss : Boss.values())
		{
			if (first == null && boss.getUnlockSlots() > 0)
			{
				first = boss;
			}
		}

		Progress progress = new Progress();
		assertTrue(progress.isUnlocked(Boss.OBOR));
		assertFalse(progress.isUnlocked(first));
		for (int item = 1; item <= first.getUnlockSlots(); item++)
		{
			progress.addLogItem(item);
		}
		// The slots alone aren't enough.
		assertFalse(progress.isUnlocked(first));
		for (int kill = 1; kill < first.unlockKills(); kill++)
		{
			progress.addKill(first.previous());
		}
		assertFalse(progress.isUnlocked(first));
		progress.addKill(first.previous());
		assertTrue(progress.isUnlocked(first));
		assertFalse(progress.isUnlocked(Boss.values()[Boss.values().length - 1]));
		assertEquals(first.getUnlockSlots(), progress.totalSlots());
	}

	@Test
	public void logItemsRememberTheKillTheyDroppedOn()
	{
		Progress progress = new Progress().migrate();
		progress.addKill(Boss.OBOR);
		progress.addKill(Boss.OBOR);
		assertTrue(progress.addLogItem(20756, Boss.OBOR));
		assertEquals("obor", progress.logDrop(20756).boss);
		assertEquals(2, progress.logDrop(20756).kills);
		// A second one doesn't move it.
		progress.addKill(Boss.OBOR);
		assertFalse(progress.addLogItem(20756, Boss.OBOR));
		assertEquals(2, progress.logDrop(20756).kills);

		Gson gson = new Gson();
		assertEquals(2, gson.fromJson(gson.toJson(progress), Progress.class).migrate().logDrop(20756).kills);
		// Saves from before it was kept still load, without a drop KC.
		Progress old = gson.fromJson("{\"logItems\":[20756]}", Progress.class).migrate();
		assertTrue(old.hasLogItem(20756));
		assertNull(old.logDrop(20756));
	}

	@Test
	public void aBossYouveFoughtStaysUnlocked()
	{
		Progress progress = new Progress();
		Boss last = Boss.values()[Boss.values().length - 1];
		assertFalse(progress.isUnlocked(last));
		progress.addKill(last);
		assertTrue(progress.isUnlocked(last));
	}

	@Test
	public void unlockKillsAreAboutTenMinutesOfTheBossBefore()
	{
		for (Boss boss : Boss.values())
		{
			if (boss.getUnlockSlots() == 0)
			{
				assertEquals(0, boss.unlockKills());
				continue;
			}
			assertEquals(0, boss.unlockKills() % 5);
			double killMinutes = boss.previous().typicalKillSeconds() / 60;
			double minutes = boss.unlockKills() * killMinutes;
			// Rounding up to a multiple of 5 adds at most 5 kills.
			assertTrue(boss + " needs " + minutes + " minutes", minutes >= 10 && (minutes < 10 + 5 * killMinutes || boss.unlockKills() == 5));
		}
	}

	@Test
	public void oldSavesWithMissingFieldsStillLoad()
	{
		Progress loaded = new Gson().fromJson("{\"bosses\":{\"obor\":{\"kills\":3}}}", Progress.class);
		assertEquals(3, loaded.kills(Boss.OBOR));
		assertEquals(0, loaded.logCount(java.util.List.of(20756)));
		assertEquals(0, loaded.kills(Boss.VORKATH));
	}
}

package com.idlebosses;

import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import org.junit.Test;

// Plays the ladder many times at a typical pace and prints how long each unlock takes, for tuning Boss.unlockSlots. Each
// simulated player first gets the kills the next boss needs, then fights whichever boss gives new log slots fastest.
public class ProgressionTest
{
	private static final int PLAYERS = 200;
	private static final double GIVE_UP_HOURS = 2_000;

	@Test
	public void everyBossUnlocksInAReasonableTime() throws Exception
	{
		DropData data = DropDataTest.load();
		Boss[] bosses = Boss.values();
		double[][] unlockHours = new double[bosses.length][PLAYERS];
		Map<Boss, Map<Integer, Double>> chances = new EnumMap<>(Boss.class);
		for (Boss boss : bosses)
		{
			chances.put(boss, DropRates.perKill(data, data.boss(boss)));
		}

		for (int p = 0; p < PLAYERS; p++)
		{
			Random random = new Random(p);
			LootRoller roller = new LootRoller(data, random);
			// Like the game, an item fills its slot on every boss whose log it's on.
			Set<Integer> owned = new HashSet<>();
			int[] kills = new int[bosses.length];
			double seconds = 0;
			for (int b = 0; b < bosses.length; b++)
			{
				unlockHours[b][p] = bosses[b].getUnlockSlots() == 0 ? 0 : -1;
			}

			while (unlockHours[bosses.length - 1][p] < 0 && seconds < GIVE_UP_HOURS * 3600)
			{
				Boss boss = gateBoss(bosses, owned.size(), kills);
				if (boss == null)
				{
					boss = fastestSlots(data, chances, bosses, owned, kills);
				}
				if (boss == null)
				{
					break;
				}

				seconds += boss.typicalKillSeconds();
				kills[boss.ordinal()]++;
				DropData.BossDrops drops = data.boss(boss);
				for (Loot loot : roller.roll(drops, random.nextInt(30) == 0))
				{
					if (drops.log.contains(loot.getItemId()))
					{
						owned.add(loot.getItemId());
					}
				}
				for (int b = 0; b < bosses.length; b++)
				{
					if (unlockHours[b][p] < 0 && unlocked(bosses[b], owned.size(), kills))
					{
						unlockHours[b][p] = seconds / 3600;
					}
				}
			}
		}

		System.out.println("Boss                      slots  kills   median hours   90th percentile");
		for (int b = 0; b < bosses.length; b++)
		{
			double[] hours = unlockHours[b].clone();
			Arrays.sort(hours);
			double median = hours[PLAYERS / 2];
			double p90 = hours[PLAYERS * 9 / 10];
			System.out.printf("%-25s %5d  %5d   %12.1f   %15.1f%n", bosses[b].getDisplayName(), bosses[b].getUnlockSlots(),
				bosses[b].unlockKills(), median, p90);
			assertTrue(bosses[b] + " never unlocks for some players", hours[0] >= 0);
		}
	}

	static boolean unlocked(Boss boss, int slots, int[] kills)
	{
		Boss previous = boss.previous();
		return slots >= boss.getUnlockSlots() && (previous == null || kills[previous.ordinal()] >= boss.unlockKills());
	}

	// The unlocked boss that gives a new log slot soonest, like a player chasing unlocks would fight, or null.
	static Boss fastestSlots(DropData data, Map<Boss, Map<Integer, Double>> chances, Boss[] bosses, Set<Integer> owned,
		int[] kills)
	{
		Boss fastest = null;
		double best = 0;
		for (Boss boss : bosses)
		{
			if (!unlocked(boss, owned.size(), kills))
			{
				continue;
			}
			double slotsPerSecond = 0;
			for (int itemId : data.boss(boss).log)
			{
				if (!owned.contains(itemId))
				{
					slotsPerSecond += chances.get(boss).getOrDefault(itemId, 0.0);
				}
			}
			slotsPerSecond /= boss.typicalKillSeconds();
			if (slotsPerSecond > best)
			{
				best = slotsPerSecond;
				fastest = boss;
			}
		}
		return fastest;
	}

	// The newest unlocked boss, while the next boss still needs more kills of it, or null. A player going up the
	// ladder fights it first.
	static Boss gateBoss(Boss[] bosses, int slots, int[] kills)
	{
		for (Boss boss : bosses)
		{
			if (!unlocked(boss, slots, kills))
			{
				Boss previous = boss.previous();
				return previous != null && kills[previous.ordinal()] < boss.unlockKills() ? previous : null;
			}
		}
		return null;
	}
}

package com.idlebosses;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.List;
import java.util.Random;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class ShopTest
{
	private static Progress progress(long coins)
	{
		Progress progress = new Progress().migrate();
		progress.coins = coins;
		return progress;
	}

	@Test
	public void oldSavesStartWithWhatTheyLooted()
	{
		Progress loaded = new Gson().fromJson("{\"gpLooted\":5000000}", Progress.class).migrate();
		assertEquals(5_000_000, loaded.coins());
		loaded.addLootValue(1_000);
		assertEquals(5_001_000, loaded.gpLooted);
		assertEquals(5_001_000, loaded.coins());
		assertTrue(loaded.gear.isEmpty());
		assertFalse(loaded.cannon.owned);
	}

	@Test
	public void ladderTiersAreBoughtInOrder()
	{
		Progress progress = progress(100_000_000);
		assertFalse(Shop.buy(progress, Gear.AMULET_OF_GLORY));
		assertTrue(Shop.buy(progress, Gear.AMULET_OF_POWER));
		assertTrue(Shop.buy(progress, Gear.AMULET_OF_GLORY));
		assertEquals(100_000_000 - 25_000 - 500_000, progress.coins());
		assertEquals(Gear.AMULET_OF_GLORY, progress.best(Gear.Slot.AMULET));
		assertFalse(Shop.buy(progress, Gear.AMULET_OF_GLORY));
	}

	@Test
	public void boughtWeaponsAreWieldedAndCanBeSwapped()
	{
		Progress progress = progress(1_000_000);
		assertTrue(Shop.buy(progress, Gear.DRAGON_SCIMITAR));
		assertEquals(Gear.DRAGON_SCIMITAR, progress.wielded());
		assertTrue(Shop.buy(progress, Gear.MAGIC_SHORTBOW));
		assertEquals(Gear.MAGIC_SHORTBOW, progress.wielded());
		assertTrue(Shop.wield(progress, Gear.DRAGON_SCIMITAR));
		assertEquals(Gear.DRAGON_SCIMITAR, progress.wielded());
		assertFalse(Shop.wield(progress, Gear.TWISTED_BOW));
	}

	@Test
	public void bossWeaponsNeedTheirLogItems()
	{
		Progress progress = progress(1_000_000_000);
		assertEquals(List.of(ItemID.WBR_VOIDWAKER_HILT, ItemID.WBR_VOIDWAKER_BLADE, ItemID.WBR_VOIDWAKER_GEM),
			Shop.missing(progress, Gear.VOIDWAKER));
		assertFalse(Shop.buy(progress, Gear.VOIDWAKER));
		progress.addLogItem(ItemID.WBR_VOIDWAKER_HILT);
		progress.addLogItem(ItemID.WBR_VOIDWAKER_BLADE);
		assertFalse(Shop.buy(progress, Gear.VOIDWAKER));
		progress.addLogItem(ItemID.WBR_VOIDWAKER_GEM);
		assertTrue(Shop.buy(progress, Gear.VOIDWAKER));
		// Log items are never used up.
		assertTrue(progress.hasLogItem(ItemID.WBR_VOIDWAKER_GEM));
	}

	@Test
	public void notEnoughCoinsBuysNothing()
	{
		Progress progress = progress(10_000);
		assertFalse(Shop.buy(progress, Gear.AMULET_OF_POWER));
		assertFalse(Shop.buyCannon(progress));
		assertEquals(10_000, progress.coins());
	}

	@Test
	public void theCannonLoadsGraniteFirstAndFiresUntilEmpty()
	{
		Progress progress = progress(100_000_000);
		assertFalse(Shop.buyCannonballs(progress, false));
		assertTrue(Shop.buyCannon(progress));
		assertTrue(Shop.buyCannonballs(progress, false));
		assertEquals(0, Shop.reload(progress) - Shop.CANNON_CAPACITY);
		assertEquals(70, progress.cannon.cannonballs);

		Random random = new Random(4);
		for (int i = 0; i < Shop.CANNON_CAPACITY; i++)
		{
			Hit shot = Shop.fire(progress, Boss.OBOR, 0, random);
			assertTrue(shot.getDamage() >= 0 && shot.getDamage() <= Shop.CANNON_MAX_HIT);
		}
		assertNull(Shop.fire(progress, Boss.OBOR, 0, random));

		assertTrue(Shop.buyCannonballs(progress, true));
		Shop.reload(progress);
		assertEquals(30, progress.cannon.loadedGranite);
		assertEquals(70, progress.cannon.granite);
		assertEquals(70, progress.cannon.cannonballs);
	}

	@Test
	public void theKodaiWandSavesSomeBalls()
	{
		Progress progress = progress(1_000_000_000);
		Shop.buyCannon(progress);
		Random random = new Random(6);
		int shots = 0;
		int used = 0;
		for (int i = 0; i < 200; i++)
		{
			Shop.buyCannonballs(progress, false);
			Shop.reload(progress);
			while (progress.cannon.loaded > 0)
			{
				int before = progress.cannon.loaded;
				Shop.fire(progress, Boss.OBOR, Gear.KODAI_WAND.getValue() / 100.0, random);
				used += before - progress.cannon.loaded;
				shots++;
			}
		}
		assertEquals(0.85, (double) used / shots, 0.01);
	}
}
